window.DOSIK=window.DOSIK||{};DOSIK["ip_4"]={"1":[{"t":"flow","title":"사업화 유형의 리스크","steps":["IP 매각이 가장 낮음","전략적 제휴","라이선싱","합작투자","기업 매수","벤처 창업이 가장 높음"]},{"t":"tree","title":"지식재산권의 사업화 방법","root":"지식재산권의 사업화 방법","branches":[["설립·매수","스타트업 설립, 기존 법인 매수, 합작투자 기업 설립"],["이용·판매","라이선싱, 지식재산권 판매"],["수익화","담보 대출, 특허 소송 등 적극적 권리행사를 통한 수익화"]]},{"t":"cause","title":"스타트업 창업","causes":["지식재산이 제품으로 판매되기 전에 제품과 사업지원 인프라 개발을 위한 상당한 선행투자가 필요하다."],"result":"새로운 스타트업을 설립하는 경우 리스크와 잠재수익이 모두 가장 높다.","effects":["지식재산권은 기술적 능력을 외부에 증명하는 수단이 된다.","후발주자의 시장 진입을 차단하는 무기가 된다.","기업가치 산정 시 무형자산으로 반영된다."]},{"t":"vs","title":"기업 매수와 스타트업 창업","cols":[{"name":"기업 매수","items":["기업 M&A는 기술적 경쟁 우위나 시장 점유율을 높이기 위해 상대 기업의 지식재산을 획득하는 것이 주된 목적이 될 수 있다.","대상이 이미 개발과 인적·물적 구조를 갖추고 있어 스타트업 창업보다 리스크가 낮고 사업화 기간이 단축되며 통제력을 유지할 수 있다.","상당한 투자가 요구되어 잠재 수익이 감소하고, 기업문화 융합의 어려움과 원치 않는 자산·부채 인수 및 돌발채무의 부담이 따를 수 있다."]},{"name":"스타트업 창업","items":["리스크와 잠재수익이 모두 가장 높다."]}]}],"2":[{"t":"table","title":"합작투자","head":["항목","내용"],"rows":[["개념","목표한 사업을 위해 참여 기업들이 지식재산을 공유하고 공동 목표를 위해 협력하는 투자 관계로, 조인트 벤처라고도 불린다."],["리스크","참여 기업의 보완적인 기술과 자원으로 리스크가 감소한다."],["수익","리스크와 수익을 소유자 간에 나누므로 스타트업 설립이나 기업매수보다 수익은 낮아진다."],["관리","참여 기업 간의 상이한 목표와 지배력 수준 차이로 관리에 어려움이 있을 수 있다."]]},{"t":"def","term":"전략적 제휴","text":"둘 이상의 기업이 각자의 지식재산을 공유하거나 상호 협력하여 새로운 시너지를 창출하기 위해 체결하며, 제휴에 따른 위험과 보상은 상호 협력 분야로 제한된다."},{"t":"vs","title":"제휴의 방향","cols":[{"name":"수직적 제휴","items":["한 기업이 다른 기업이 개발한 제품을 시장에 판매하여 수익 일부를 얻는 것"]},{"name":"수평적 제휴","items":["특정 시장 공략을 위해 상대 기업의 전문화된 기술을 활용하는 것"]}]}],"3":[{"t":"vs","title":"라이선싱","cols":[{"name":"기술 보유자","items":["자사 지식재산을 다른 기업에 이용 허가하여 수익을 창출하는 방법","잠재수익도 라이선시에게 비례적으로 이전되어 라이선서의 수익은 줄어든다."]},{"name":"기술 도입자","items":["기술적 과제를 해결하고 사업적 비전을 향상시키는 수단","제품 개발·제조·마케팅을 맡는 라이선시(기술도입자)에게 리스크 대부분이 이전된다."]}]},{"t":"cause","title":"라이선싱의 리스크","causes":["리스크 대부분이 제품 개발·제조·마케팅을 맡는 라이선시(기술도입자)에게 이전된다."],"result":"앞서 설명한 사업화 유형들보다 리스크가 낮다.","effects":["리스크가 이전되는 만큼 잠재수익도 라이선시에게 비례적으로 이전된다."]},{"t":"def","term":"지식재산의 매각","text":"기술 보유자가 필요하지 않거나 부가가치를 창출하기 어려운 지식재산을 타 기업에 전달하는 방법으로, 무형자산을 처분하여 현금·주식·영업권 등을 확보할 수 있다.","ex":["다른 기업에 바로 판매하는 것은 리스크가 가장 낮은 방법이지만 높은 리스크를 구매자에게 넘기는 것이므로 상대적으로 수익은 낮아진다.","스타트업이 아이디어 개발부터 시장 진입까지 직접 하기 어려우면 기술을 일정 수준까지 개발한 후 지식재산권을 대기업에 매각하며 기술을 지도하는 것을 사업 전략으로 취할 수 있다."]}],"4":[{"t":"def","term":"기술창업","text":"혁신적인 기술이나 아이디어로 새 시장을 만들어 제품·서비스를 생산·판매하는 창업 형태로, 지식재산의 보호와 활용이 중요하다.","ex":["대체로 제조업, 전문서비스업, 지식문화사업 분야의 창업을 뜻하지만 해당 기업군을 정의하는 일관된 용어는 없다."]},{"t":"table","title":"기술창업의 지식재산 전략","head":["권리","역할"],"rows":[["특허","기술 혁신을 지킨다."],["상표","제품과 브랜드를 식별한다."],["저작권","창작물을 보호한다."]]},{"t":"vs","title":"기술창업과 일반창업","cols":[{"name":"기술창업","items":["독점성과 경쟁력이 강하다.","기술수명주기가 있어 오래 유지하기 어렵다."]},{"name":"지식기술창업의 범주","items":["주로 IT융합 분야의 콘텐츠·소프트웨어, 제조업 융합 분야, 지식 기반 서비스업이 포함된다.","생계형 창업은 제외하는 것이 일반적이다."]}]}],"5":[{"t":"tree","title":"창업 초기 애로","root":"기술창업 초기 애로","branches":[["핵심 인력","아이템 사업화를 가능하게 하는 핵심 기술인력을 확보하지 못하면 창업 자체가 불가능할 수 있다."],["역량","사업성 있는 아이템을 포착하고 기술을 사업화할 역량이 중요한데, 많은 기업이 이 역량 확보에 실패한다."],["가치 평가","매출이 적어 기술 수준과 성장성 같은 무형의 가치를 평가받아야 하지만 이를 위한 시스템이 취약하다."],["규제 비용","각종 절차와 규제에서 생기는 비용이 진입장벽이 되며, 사업화에 필요한 인허가·규제도 유무형의 비용으로 작용한다."],["제도 검토","제도적 검토 없이 사업을 시작하면 제품이 나와도 시장에 출시할 수 없는 문제가 생길 수 있으므로 법적 구조와 규제 준수 확인이 필요하다."]]}],"6":[{"t":"flow","title":"기술창업 기본 절차","steps":["창업구상 단계: 구체적인 아이템을 정하기 전에 창업자의 역량을 점검하고 시장·기술 조사로 가장 적합한 아이템을 구상","창업계획 단계: 사업 타당성 검토와 사전계획 수립으로 시행착오를 줄이고 사업계획서를 작성","사업실행 단계: 선정된 창업 아이템의 사업화를 위해 회사 설립, 공장 설립, 조직·인력 확보, 경영관리를 진행"]},{"t":"def","term":"지식재산 조사 분석","text":"창업구상 단계에는 사업 아이템 탐색 뒤에 선행기술 조사, 법적 문제점 검토, 지식재산 출원을 하는 지식재산 조사 분석이 포함된다.","ex":["기술창업의 기본 절차는 사업 아이템을 정하고 객관적 검증을 거쳐 실현 가능한 계획을 세운 뒤 창업을 실현하는 과정이다."]}],"7":[{"t":"table","title":"창업 지원기관·제도","head":["기관·제도","내용"],"rows":[["창업보육센터(인큐베이터)","초기 창업자에게 사무 공간, 멘토링, 자금 지원, 네트워킹 기회 등을 제공해 창업을 돕는다."],["스핀오프 창업","기존 기업이나 연구기관이 개발한 기술을 이전받아 독립 회사를 세우는 형태로 기술적 리스크가 상대적으로 낮다."],["기술지주회사","대학이나 연구기관이 보유한 기술의 상용화를 위해 설립된 회사로 기술이전과 사업화를 전문적으로 지원한다."],["정부 창업지원","예비창업패키지, 초기창업패키지, 청년창업사관학교, TIPS 같은 정부 창업지원 매칭자금으로 초기 창업자금을 확보하는 형태도 있다."],["전략","스톡옵션제도로 인재를 영입하고, B2G 사업 확대를 위해 NET·NEP 인증제도를 활용하는 것도 전략이 될 수 있다."]]}],"8":[{"t":"tree","title":"창업 성공 요소","root":"창업의 성공적 수행에는 사람, 아이디어, 시장, 자본이라는 요소가 필요하며 이 요소들이 상호작용해 성공 여부를 좌우한다.","branches":[["사람","동업자는 창업자와 함께 금전·현물·기술을 투자하고 사업부문별 역할을 맡아 그 과실을 분배받는 사람으로 창업자 다음으로 중요한 구성원이다."],["아이디어","기술창업의 아이디어는 혁신성과 실현 가능성을 갖추어야 하며, 지식재산권 확보가 가능한 아이디어가 경쟁우위와 투자 유치에 좋다."],["시장","제품·서비스에 대가를 지급하고 구입하려는 고객 집단으로, 시장 가능성을 보고 제품을 개발하는 쪽이 기술 우수성만 믿고 개발하는 것보다 성공 가능성이 높다."],["자본","기술창업의 초기 자본은 주로 엔젤 투자자, 벤처캐피털, 정부 지원 프로그램을 통해 조달하는 것이 일반적이다."]]},{"t":"vs","title":"자기자본과 타인자본","cols":[{"name":"자기자본","items":["조달된 자본 중 상환 의무가 없는 자본으로, 법인기업에서는 주주나 출자자가 투자한 금액을 말한다."]},{"name":"타인자본","items":["친인척·지인·금융기관 차입처럼 주주나 출자자 투자 이외에 타인으로부터 조달하는 자금으로 상환 의무가 있다."]}]},{"t":"def","term":"비즈니스 모델","text":"수익을 창출할 수 있는 명확하고 실현 가능한 모델로, 가격 책정, 판매 전략, 수익 구조 등을 포함한다."}],"9":[{"t":"tree","title":"M&A 동기","root":"전통적으로 M&A는 규모의 경제와 시장점유율 확대가 목적이었으나 최근에는 지식재산이 M&A의 주요 요인으로 작용하고 있다.","branches":[["독점적 이익","다른 기업의 지식재산을 획득해 독점적 기술·제품을 보유하고 경쟁사보다 우월한 위치를 차지하려는 동기이다."],["효율적 통제","원재료 공급부터 판매까지 장악하는 수직적 합병은 협상·조정·커뮤니케이션 비용과 광고·포장 비용을 줄일 수 있다."],["수익성 확보","채산성이 없거나 성장률이 낮을 것으로 예상되는 지식재산을 매각하고 주력업종에 집중하려는 동기이다."]]},{"t":"tree","title":"M&A 효과","root":"M&A의 효과","branches":[["효율성","규모의 경제와 범위의 경제를 실현하고 기술과 자원의 시너지를 극대화해 효율성을 높일 수 있다."],["다변화","지리적 다변화와 새 고객층 확보를 이루고 여러 시장에 리스크를 분산해 안정적 성장을 꾀할 수 있다."],["신기술","신기술을 보유한 기업을 인수하면 내부 기술 개발에 드는 시간과 비용을 절감하고 빠르게 변하는 시장에서 혁신을 주도할 수 있다."],["인재","인수 대상 기업의 전문인력과 인재를 자사로 흡수해 인적 자원의 질을 높이고 핵심 역량을 강화할 수 있다."],["경쟁자","시장 내 경쟁자를 제거하거나 약화시키기 위해 M&A를 하면 시장점유율을 높이고 가격 책정 등에서 우위를 점할 수 있다."]]}],"10":[{"t":"cause","title":"M&A 지식재산 평가","causes":["M&A가 기업의 개별 이전이 아닌 포괄적 이전이다."],"result":"개별 지식재산보다 기업 전체의 가치를 평가하는 것이 합리적이다.","effects":["보유 지식재산은 대상 기업에 대한 중요한 실사 항목 중 하나이다."]},{"t":"table","title":"자산실사(due diligence)","head":["확인 항목","내용"],"rows":[["조사","매입 대상 기업이 소유하거나 사용하는 지식재산은 자산실사(due diligence)를 통해 조사해야 한다."],["법적 리스크","대상 IP가 법적 논란이나 침해 분쟁에 휘말리지 않았는지 확인해 매입 후 법적 리스크를 최소화해야 한다."],["보호기간","등록된 IP의 보호기간이 곧 만료될 가능성이 있으면 가치를 재평가하거나 만료를 기다려 실시하는 방안을 검토한다."],["공유 IP","매입 대상 기업이 다른 회사와 공유하는 IP는 구매자가 소유하고 라이선스를 판매자에게 줄지, 그 반대로 할지 명확히 합의해야 한다."]]}],"11":[{"t":"table","title":"M&A 특허 전략","head":["전략","내용","사례"],"rows":[["성장 전략","제품라인 개발이나 신규 시장 확장 같은 장기 문제와 관련되며, 향후 18개월에서 5년의 경쟁 상황에 초점을 둔다. M&A로 새로운 시장의 특허를 획득해 그 시장에 성공적으로 진입할 수 있다.","TI는 Amati Communications를 인수해 25개의 DSL 특허를 얻었고, 이 특허가 DSL 기술표준으로 채택되어 시장을 선도했다."],["유지 전략","낮은 성장률이나 이윤 축소 같은 당면 문제를 해결하기 위해 12~18개월 정도 걸리는 방안을 제시하며 이윤 제고와 수입 증대를 목표로 한다. 특허위치에서 경쟁력이 약한 부분을 강화하고 자사 보유특허를 상호 라이선싱이나 로열티 획득 수단으로 활용한다.","Canon은 잉크젯 카트리지, 용지 등 프린터 소모품 관련 기술을 모두 특허화하는 유지 전략으로 프린터 시장의 우위를 지켰다."],["처분 전략","경영실적이 나쁘거나 비전이 없는 사업의 특허, 주력 사업과 관련성이 낮은 특허 등을 타사에 판매해 수익 기회를 만드는 전략이다.","Avery Dennison은 경쟁사의 강력한 특허 때문에 힘을 못 쓰던 사업의 특허를 처분하고, 그 수입을 성장 중인 사업에 재투자했다."]]}],"12":[{"t":"def","term":"IP 라이선싱","text":"지식재산권 소유자가 다른 개인이나 기업에 해당 권리를 사용할 수 있는 권한을 부여하는 계약이며, 권리 양도와는 다르다.","ex":["라이선스를 주는 자가 라이선서(licensor)이고 라이선스를 받는 자가 라이선시(licensee)이다."]},{"t":"vs","title":"독점과 비독점 라이선스","cols":[{"name":"독점 라이선스","items":["특정 라이선시에게만 사용 권한을 주고 다른 누구에게도 같은 권한을 주지 않는다.","지역, 기간, 제품·서비스 영역 등을 제한해 허여하는 경우가 있어 분쟁 소지를 막으려면 영역을 잘 설정해야 한다."]},{"name":"비독점 라이선스","items":["여러 라이선시에게 같은 지식재산 사용을 허용한다."]}]},{"t":"vs","title":"라이선싱 아웃과 인","cols":[{"name":"라이선싱 아웃","items":["라이선스를 타인에게 주는 것"]},{"name":"라이선싱 인","items":["타인의 권리에 대해 라이선스를 도입하는 것"]}]},{"t":"vs","title":"전용실시권과 통상실시권","cols":[{"name":"전용실시권","items":["특허권의 전용실시권은 등록이 효력 발생요건이다.","설정·등록되면 그 범위 안에서는 특허권자도 특허발명을 실시할 수 없고 전용실시권자가 실시할 권리를 독점한다."]},{"name":"통상실시권","items":["계약에 의한 합의만으로 효력이 발생한다.","계약에 의한 실시권은 사적 자치의 원칙에 따라 기간을 한정하거나 실시 지역, 실시 제품 또는 형태를 한정해 설정할 수 있다."]}]},{"t":"vs","title":"폐쇄형과 개방형 라이선스","cols":[{"name":"폐쇄형 라이선스","items":["양자 간 계약으로 체결되며 라이선시만 권리를 쓸 수 있다."]},{"name":"개방형 라이선스","items":["일정 조건 아래 공개되어 누구나 이용할 수 있다.","주로 소프트웨어 분야에서 쓰이며, 오픈소스 소프트웨어는 자유롭게 이용·복제·재배포·수정할 수 있는 것이 특징이다."]}]},{"t":"def","term":"묵시적 라이선스","text":"정당한 권한자가 특허제품을 정당하게 유통했을 때 구매자에게 권리자가 침해를 주장할 수 없게 되는 것으로, 권리 소진 법리에 따른다."}],"13":[{"t":"vs","title":"라이선서와 라이선시의 효과","cols":[{"name":"라이선서","items":["기술을 직접 제공하지 않고도 수익을 얻는다.","라이선시의 실시에 따른 실시료를 징수해 수익을 얻으며, 경상실시료로 합의하면 라이선시의 매출이 늘수록 실시료 수입도 늘어난다.","라이선시의 영업을 통해 새 시장에 진입할 수 있다.","공동 개발·마케팅으로 라이선스 대상 기술이 산업 표준이 되도록 노력할 수 있고 실질적 표준 기술이 되게 할 수도 있다."]},{"name":"라이선시","items":["해당 기술로 제품을 개발할 수 있어 중소기업과 스타트업에 중요한 전략 수단이 된다.","필요한 기술의 권리를 받아 제품 가치를 높이고, 해당 권리로 인한 분쟁 위험도 제거해 안정적으로 사업을 할 수 있다.","새 시장 진입에 따른 설비 투자 비용과 사업 불확실성을 부담하게 된다.","유용한 특허를 가진 경우 크로스 라이선스로 서로 사용하게 할 수 있고, 제3자 권리 침해 시에도 공동 대응으로 분쟁 대응 역량을 강화할 수 있다."]}]},{"t":"def","term":"개방형 혁신","text":"라이선싱 활동은 관련 시장 확대와 기술개발 가속으로 기업 가치를 높이는 개방형 혁신의 일종으로 볼 수 있다."}],"14":[{"t":"table","title":"라이선스 계약","head":["항목","내용"],"rows":[["계약 조건","사용 범위, 사용 기간, 지불 방식, 지식재산의 유지·보호에 관한 사항이 포함되며 양측의 협상으로 정한다."],["필수요소","계약 당사자, 실시허락의 대상 기술, 실시권의 세 가지이며, 실시료는 법적 필수요소가 아니다."],["성립","계약자유의 원칙에 따라 전용실시인지 통상실시인지를 가리지 않고 합의만으로 성립하며 제3자의 동의나 행정청의 허가·등록이 필요 없다."],["공유특허권자","다른 공유자의 동의를 받지 않으면 제3자에게 실시권을 허락할 수 없다."],["신고","국제 라이선스 계약이나 기술도입 계약을 체결할 때는 주무관청이나 공정거래위원회에 소정 사항을 신고해야 하는 경우도 있다."]]},{"t":"tree","title":"분쟁 해결 조항","root":"분쟁 해결 조항","branches":[["방법","중재, 조정, 법정 소송 등 양측이 합의한 방법으로 분쟁을 해결하게 한다."],["국제 계약","관할 법원, 적용 법률, 분쟁 해결 절차 등을 명확히 규정해 법적 불확실성을 줄인다."]]}],"15":[{"t":"cause","title":"크로스 라이선스","causes":["둘 이상의 기업이 각자의 지식재산권을 상대방에게 실시하도록 허여한다.","경제적 가치가 동등하면 보통 무상으로 계약한다.","상호 허여하는 권리의 가치 차이가 있으면 해당 차액을 지불하고 사용하기도 한다."],"result":"다른 기업과의 특허 소송에 드는 비용·인력·시간을 절약할 수 있다.","effects":["글로벌 기업 간에 체결이 늘고 있다."]},{"t":"table","title":"계약 종류","head":["계약","내용"],"rows":[["Option Agreement","최소한의 기술을 개시받은 뒤 일정한 검토기간이 지나 계약체결 여부를 결정하도록 하는 계약이다."],["Cross License Agreement","실시권의 상호 허여에 관한 계약이다."],["Patent License Agreement","특허의 실시권 허여 계약이다."]]}],"16":[{"t":"flow","title":"라이선스 계약 절차","steps":["1단계: 라이선서 입장에서 라이선싱 필요성과 사업화 전략 검토, 대상 선정, 지식재산 마케팅 등 기술 마케팅의 준비와 실시","2단계: 라이선시 발굴·선정 뒤 기술료 등 거래 조건을 협상하고 협상 결과를 계약서로 작성해 체결","3단계: 필요한 신고·승인, 계약 실행, 기술료 수령 등 사후관리와 계약 완료"]},{"t":"tree","title":"라이선싱 마케팅","root":"라이선싱 마케팅과 라이선시 선정","branches":[["마케팅","지식재산을 도면화·자료화·매뉴얼화해 유형화하고 테크노마트·전시회 같은 오프라인과 온라인 마케팅을 활용한다."],["라이선시 선정","실시·사용 능력, 협력관계 지속을 위한 신뢰성, 사업영역과 전략에서의 상충 가능성 등을 고려한다."],["비밀유지","라이선서가 기술자료를 작성·송부할 경우 그 기술자료에 대한 비밀유지 의무를 라이선시에게 주지시켜야 한다."]]},{"t":"vs","title":"기술료 결정","cols":[{"name":"시장접근법","items":["시장에서 적용되는 산출 방식과 요율을 이용한다."]},{"name":"순이익 배분 방식","items":["계약기간의 순이익을 기술 기여도에 따라 배분한다."]}]},{"t":"def","term":"계약서","text":"기술제공 내용과 조건을 법적 구속력 있는 문서로 보존하고 계약 이행·해석의 기준이자 분쟁 해결의 기초 근거가 된다."}],"17":[{"t":"tree","title":"라이선싱 기술료의 유형","root":"라이선싱 기술료의 유형에는 정액 기술료, 마일스톤 기술료, 경상 기술료 등이 있고 한 계약에 둘 이상의 유형이 함께 포함될 수도 있다.","branches":[["정액 기술료","계약 시 한 번에 지불하는 고정 금액이며, 계약 체결 이후 특정 시점에 분납으로 나누어 받는 방식도 포함한다."],["마일스톤 기술료","조건 달성부 기술료라고도 하며, 라이선시가 특정 개발 단계나 성과 조건을 달성할 때마다 지불한다."],["경상 기술료","라이선스받은 기술로 만든 제품·서비스의 판매에 따라 지속적으로 지불하며 통상 총매출액의 일정 비율로 계산한다."],["미실시 기술료","기술이전 후 미실시에 대한 페널티로 지급한다."],["최저 기술료","판매가 없어도 최저 금액을 낸다."]]}],"18":[{"t":"vs","title":"장기와 단기 라이선스","cols":[{"name":"장기 라이선스","items":["보통 선급금을 적게, 경상 실시료는 높게 설정하며, 라이선시가 스타트업이나 작은 기업일 때 양측에 유리할 수 있다.","라이선시가 사업을 포기하거나 재무적 어려움을 겪으면 라이선서 입장에서는 위험 부담이 있다."]},{"name":"단기 라이선스","items":["짧은 기간의 라이선스는 초기 선급금이 많고 경상 로열티는 상대적으로 적거나 아예 초기에 일시금으로 지급하는 방식이다.","과거 지식재산권을 침해한 라이선시에게 손해액을 배상받는 경우나 라이선시 재정이 불투명한 경우에 쓰일 수 있다."]}]},{"t":"vs","title":"독점과 비독점 라이선스 조건","cols":[{"name":"비독점 라이선스","items":["양 당사자의 위험을 줄일 수 있다.","라이선서는 여러 사람에게 허여해 실시료 수입을 극대화하고 라이선시의 개량기술도 이익으로 얻는다."]},{"name":"독점 라이선스","items":["그 범위 안에서 권리자도 실시할 수 없고 중첩되는 라이선스를 제3자에게 줄 수 없다.","라이선시의 시장점유율과 제조·판매능력을 면밀히 조사해야 한다."]}]},{"t":"tree","title":"개량기술과 그랜트백","root":"라이선스 계약의 개량기술 처리에 관한 합의는 보통 그랜트백(grant back) 조항으로 불린다.","branches":[["라이선서","라이선시가 개량한 기술에 일정한 권리를 갖는 쪽이 유리하다."],["양 당사자","개량기술을 서로 일정 조건으로 자유롭게 실시하게 하거나 공유하거나, 별도 라이선스를 체결할 의무 또는 협상 우선권을 주는 조항을 둘 수 있다."],["표준 기술","핵심 라이선스 기술이 표준일 때는 개량기술이 표준에 통합되지 못하면 쓸모가 거의 없어, 라이선서가 라이선시의 개량기술에 대한 권리를 보유하는 것이 특히 중요하다."]]},{"t":"table","title":"재실시권과 최저 실시료","head":["항목","내용"],"rows":[["한국 법제","실시권자는 권리자의 동의 없이는 자신의 실시권을 양도하거나 재실시권을 설정할 수 없다."],["재실시권","재실시권 허락 권리를 라이선시에게 주는 경우에도 재실시권은 라이선서와 라이선시의 기존 계약 조건을 초과할 수 없다."],["최소 수량","실시 수량에 최소 수량을 정하는 것은 라이선서 입장에서 최소한의 실시료를 확보하는 기능을 하므로 최저 실시료를 정하는 것과 같다."]]}],"19":[{"t":"def","term":"지식재산 가치평가 방법","text":"일반적으로 소득접근법, 비용접근법, 시장접근법이 쓰이며, 로열티공제법은 소득접근법과 시장접근법을 결합한 방법으로 지식재산 금융 평가에 널리 활용된다."},{"t":"vs","title":"IP가치평가와 기술가치평가","cols":[{"name":"IP가치평가","items":["IP를 평가대상으로 하며 두 평가는 원칙과 방법론이 상당 부분 유사하다.","IP 없이 기술·노하우만 평가하지 않는다.","평가대상이 권리 자체이므로 IP에 중대한 권리 하자가 있으면 가치산정이 무의미할 수 있어, 권리성 분석의 역할이 기술가치평가보다 훨씬 중요하다.","미래 현금흐름의 순현재가치에서 IP가 공헌한 상대적 비중인 IP기여도를 고려해야 한다."]},{"name":"기술가치평가","items":["기술을 평가대상으로 한다는 점이 주된 차이이다.","IP 없이 기술·노하우만 평가할 수도 있다.","기존 기술가치평가 모형은 기술과 지식재산권을 구분하지 않아 지식재산에 초점을 맞춘 평가에는 한계가 있다."]}]},{"t":"def","term":"지식재산 가치평가의 전제","text":"실무상 매출액이나 현금흐름을 전제할 수밖에 없어, 기술가치평가의 기본 원칙과 평가방법이 준용되되 지식재산권의 특수성을 고려해야 한다."}],"20":[{"t":"cause","title":"지식재산 거래의 정체","causes":["지식재산의 이전·거래 활성화의 전제조건인 정확하고 신뢰도 있는 가치평가가 정착되지 못했다."],"result":"지식재산 거래가 정체되어 왔다.","effects":["지식재산 거래의 가치평가 결과는 기업의 재무상태표에 적절히 반영되어야 한다."]},{"t":"table","title":"가치평가의 법적 근거","head":["법","내용"],"rows":[["지식재산 기본법","정부는 객관적 가치평가 촉진을 위해 지식재산 가치의 평가기법과 평가체계를 확립하고 이를 거래·금융 등에 활용하도록 지원해야 한다."],["발명진흥법 개정","지식재산 가치평가의 법적 근거가 명확해졌고, 특허청이 지정한 발명의 평가기관의 평가활동을 위한 자격제도 운영 가이드라인이 마련되었다."],["발명 등의 평가","대상의 현재 또는 장래의 경제적 가치를 가액·등급 또는 점수 등으로 표시하는 것이다."],["평가 기준","대통령령으로 정하며, 평가기관은 평가 시 그 기준을 준수하여야 한다."],["평가 대상","국내외에서 출원 중이거나 등록된 발명, 상표, 영업비밀, 배치설계가 포함된다."]]}],"21":[{"t":"tree","title":"지식재산 가치평가의 용도","root":"지식재산 가치평가의 주요 용도","branches":[["금융","금융기관에 대한 담보"],["거래","매매·라이선스"],["손해배상","침해소송 손해배상액 산정"],["출자·보상","현물출자 금액 산정, 직무발명 보상금액 결정"]]},{"t":"table","title":"평가 조건","head":["항목","내용"],"rows":[["대상 기술","대상 지식재산의 권리범위를 확정해 그 범위 안의 기술을 대상 기술로 인식하며, 권리로 보호되지 않는 기술적 노하우는 구분한다."],["시장가치","적절한 마케팅 기간이 주어진 뒤 이해관계가 없는 자발적 판매자와 구매자 사이에서 평가일 현재 자산이 교환될 추정 금액이다."],["평가조건","채택 가능성이 높은 조건을 설정해 가장 효율적이고 효과적인 사용(highest and best use) 원칙을 적용해야 한다."],["목적과 용도","평가 결과는 관점과 평가요인에 따라 달라질 수 있어 평가의 목적과 용도를 명시해야 하며, 이는 평가보고서의 분석내용과 평가금액이 유효하게 적용되는 범위를 결정한다."],["대상 식별","평가자는 원칙적으로 실태조사로 대상 IP기술을 확인하되 객관적이고 신뢰할 자료가 충분하면 실태조사를 생략할 수 있다."]]}],"22":[{"t":"tree","title":"평가요소 분석","root":"평가기관은 발명 등의 평가에서 기술성, 권리성, 시장성, 사업성 및 기타 평가요인을 분석해 가액·등급·점수 산정에 반영해야 한다.","branches":[["기술성","대상 발명 등의 기술적 유용성과 경쟁력 수준을 분석하는 것으로 완성도·구현 가능성, 활용성·확장성, 비교우위·경쟁성 분석을 포함한다."],["권리성","대상 발명 등이 권리로서 적절히 보호되는지 분석하는 것으로 선행기술 대비 권리 안정성, 권리 보호강도, 제품·서비스 적용 여부 분석을 포함한다."],["시장성","시장환경과 시장경쟁 분석으로 적용제품이나 서비스의 시장경쟁력을 분석하는 것으로 시장규모·성장성, 시장 점유율 확보 가능성 분석을 포함한다."],["사업성","대상 발명 등을 활용한 사업의 경제성을 분석하는 것이며, 사업화 주체가 정해졌다면 그 주체의 개발·인적·마케팅 등 사업화 역량 분석도 포함한다."]]},{"t":"vs","title":"가치평가 결과 표시","cols":[{"name":"금액","items":["지식재산 가치평가는 통상 금액으로 결정받아 왔다."]},{"name":"등급","items":["최근 AI를 활용해 금액이 아닌 등급으로 가치를 평가하는 시스템도 등장했다."]}]}],"23":[{"t":"tree","title":"발명 등의 평가 방법","root":"발명 등의 평가 방법은 일반적으로 시장접근법, 소득(수익)접근법, 비용(원가)접근법의 세 가지로 구분된다.","branches":[["시장접근법","평가대상과 동일·유사한 지식재산이 활성 시장에서 거래된 가격에 근거해 상대적 가치를 산정하는 방법이다. · 거래사례비교법과 경매가 있다."],["소득(수익)접근법","평가대상의 경제적 수명기간에 사업화로 발생할 경제적 이익을 추정해 할인율로 현재가치로 환산하는 방법이다. · 기술요소법, 다기간 초과이익법, 증분수익법, 잔여가치법, 실물옵션법이 있다."],["비용(원가)접근법","대체의 경제 원리에 기초해 동일한 경제적 효익의 지식재산을 개발·구입하는 원가를 추정하는 방법으로, 기술개발비용·재생산원가·대체원가 정보가 필요하다."]]},{"t":"def","term":"접근법의 선택","text":"접근법은 서로 다른 경제적 관점에 기반하므로 상이한 가치 결과를 낳을 수 있어 가치평가 제반 상황을 감안해 신중히 결정해야 한다."}],"24":[{"t":"def","term":"로열티공제법(RFR)","text":"기업이 평가대상 IP를 보유하지 못해 제3자에게서 라이선스받는 경우를 가정해, 경제적 수명기간의 로열티의 현재가치를 기술가치로 추정하는 방법이다.","ex":["기회비용 관점에서 평가대상 IP의 가치를 추정하는 접근법이며 평가대상 IP가 경제적 이익을 창출할 수 있다는 충분한 근거가 필요하다."]},{"t":"vs","title":"로열티공제법의 분류","cols":[{"name":"수익접근법","items":["로열티 수익 흐름을 현재가치로 환원하는 점"]},{"name":"시장접근법","items":["기술시장의 로열티율 시장데이터를 쓰는 점"]}]},{"t":"flow","title":"로열티공제법 평가 순서 앞부분","steps":["평가대상 IP 분석","시장규모·매출액 예측","경제적 수명 추정","로열티율 추정","잉여현금흐름 추정"]},{"t":"flow","title":"로열티공제법 평가 순서 뒷부분","steps":["할인율 결정","할인현금흐름 추정","가치 산정","최종 검토·조정"]},{"t":"tree","title":"로열티공제법 계산","root":"로열티공제법","branches":[["초기값","대상 IP기술과 비교해 동일하거나 유사한 기술거래 로열티를 초기값으로 하고, 비교기술 간 속성 차이를 반영해 기본 로열티를 조정한다."],["IP가치","로열티율은 추정 매출액에 곱해 로열티 수입을 추정하며, 세금을 제외한 세후 로열티 수입을 현재가치화해 연도별로 합하면 IP가치가 산출된다."],["투입 변수","시장규모와 예상매출액, IP의 경제적 수명, 로열티율, 현금흐름, 할인율이 있다."]]}],"25":[{"t":"table","title":"로열티공제법 변수 추정","head":["변수","추정 방법"],"rows":[["매출계획","대상제품의 미래 수요예측이 선행되어야 하고 신제품은 관련 데이터가 없어 작성이 더 어려우므로, 관련 업계 종사자가 상식적으로 납득 가능한 수준에서 세워야 한다."],["매출예상액","업계 평균 매출규모를 기본으로 하되, 사업지배계수가 높을수록 최대시장규모에 접근하는 것으로, 높지 않으면 업계 평균 매출액에 접근하는 것으로 설정한다."],["경제적 수명","제품수명주기, 기술진보속도, 경쟁기술 출현가능성 등을 종합해 추정하며, 특허인용관계를 활용한 기술순환주기(TCT)를 참고자료로 쓰기도 한다."],["비교 로열티","사례가 없거나 매우 적으면 직접 산출하기보다 업종별 거래사례 로열티 통계에서 적정범위를 산출하고, 이것도 부족하면 상관행법 로열티 통계를 적용할 수 있다."],["최종 로열티율","기준 로열티율에 개별 IP의 기술적·권리적·시장적·사업적 특성을 포함한 조정계수를 반영하고, 전체 제품 중 평가대상 IP가 차지하는 비중까지 고려해 추정한다."],["잉여현금흐름","로열티 수익과 세금 비용 예측을 기준으로 현금유입과 현금유출의 차액을 연도별로 추정하며, 특허권의 경우 대상기간은 권리 잔존기간 이내에서 정한다."]]},{"t":"tree","title":"할인율","root":"할인율은 특정 IP를 이용한 사업의 리스크를 반영한다.","branches":[["리스크","이미 사업화된 IP보다 사업성이 검증되지 않은 신기술 IP에서 리스크가 커 달리 적용해야 한다."],["자기자본","상장기업의 자기자본 할인율은 무위험이자율에 시장수익률과 무위험이자율의 차이에 위험척도(β)를 곱한 값을 더해 산출한다."],["타인자본","지급이자의 비용인정에 따른 감세효과를 고려해 이자율×(1－법인세율)로 하고, 자기자본과 타인자본을 함께 쓰면 구성비로 가중평균해 가중평균 자본비용을 산출한다."]]},{"t":"def","term":"할인현금흐름","text":"연도별 잉여현금흐름을 (1+할인율)의 연차 거듭제곱으로 나눈 값을 합산해 IP로 인한 사업가치를 구한다."},{"t":"def","term":"로열티공제법의 한계","text":"비교 가능한 동일·유사사례를 찾기 쉽지 않고, 자리를 잡은 기업의 매출 추정에 초점을 맞춰 기술기반 스타트업의 특허 평가에는 한계가 있다."}],"26":[{"t":"def","term":"소득접근법","text":"기업의 가치가 모든 자산의 수익획득 능력에 의존한다는 가정에서 출발해, IP를 활용한 사업의 미래 기대수익을 예측하고 이를 현재가치화하며 가장 현실적이라는 장점이 있다.","ex":["장래 현금흐름을 적절한 할인율로 나누어 현재가치를 산출하는 할인현금흐름(DCF)법이 기본적으로 적용된다."]},{"t":"flow","title":"IP요소법 평가 순서","steps":["할인현금흐름으로 사업가치를 산정","IP기여도를 결정","이용률을 추정","IP 가치를 산정"]},{"t":"tree","title":"IP요소법","root":"국내에서 DCF 기반 소득접근법의 실무 방법으로는 IP요소법이 주로 쓰이며, 사업가치를 추정한 뒤 IP기여도를 곱해 IP 가치를 평가한다.","branches":[["추정 변수","현금흐름 추정기간, 연도별 잉여현금흐름, 할인율, IP기여도, 이용률 다섯 가지 변수를 추정해야 한다."],["이용률","평가 IP로 인해 발생하는 사업제품에 관련된 복수의 기술구성요소 중 평가 IP가 보호하는 비중을 뜻한다. · 제품을 구성하는 세부기술을 모두 나열해 각 비중을 분석한 뒤 평가 IP에 해당하는 세부기술을 체크해 산출하며, 비중은 원가, 소비자 구매 요인, 전문가의 정성적 평가 등이 될 수 있다."],["IP 기여분","할인현금흐름으로 얻은 사업가치는 사업가·투자자·채권자와 IP 제공자가 나누어야 할 총액이므로 평가액이 바로 나오지 않고 IP 기여분의 배분 문제가 남는다. · 초과이익 배분방식, 순이익 배분방식, 결정수익 환원방식이 주로 사용된다."],["현금흐름","손익계산서로 현금흐름을 추정할 때 감가상각비·지급이자·배당은 비용이지만 실제 현금유출이 없을 수 있어, 순이익에 감가상각비를 더해 실제 생성되는 현금총액을 계산한다."]]},{"t":"vs","title":"소득접근법의 평가","cols":[{"name":"장점","items":["제반요소가 객관적으로 결정된다면 이론적으로 가장 타당한 방법이다."]},{"name":"한계","items":["많은 가정과 변수가 개입되어 산정 결과의 변동성이 크다.","후속 연구개발 같은 연속적 투자와 단계별 수익을 평가에 포함하지 못하고, 연관 프로젝트의 보완성이나 경영의 유연성·전략적 옵션을 반영하기 어렵다."]}]}],"27":[{"t":"vs","title":"비용접근법과 시장접근법","cols":[{"name":"비용접근법","items":["기술 또는 지식재산을 개발하는 데 든 제반 개발비용을 기초로 경과기간의 가치증감분을 차감해 산정하는 방법이다.","측정이 비교적 용이하다는 장점이 있다.","수익성에 근거하지 않아 미래의 수익창출능력을 반영하지 못해, 주로 소득접근법이나 시장접근법의 보완자료로 쓴다."]},{"name":"시장접근법","items":["유사한 지식재산이 거래된 가격을 조사해 평가대상의 가치를 산정하며, 매매 사례가 없거나 비교 가능성이 없으면 적용할 수 없다.","평가대상과 유사한 자산의 거래정보가 많을 때 최적의 방법이며 라이선스 조건이나 로열티 결정에 자주 이용된다."]}]},{"t":"tree","title":"시장접근법의 요건","root":"시장접근법을 쓰려면 필요한 특성","branches":[["거래시장","비교 가능한 지식재산의 활발한 거래시장"],["거래실적","과거 거래실적"],["거래정보","접근 가능한 거래정보"],["자유의사","당사자의 자유의사에 의한 거래"]]}],"28":[{"t":"cause","title":"무형자산 인식","causes":["자산에서 발생하는 미래 경제적 효익이 기업에 유입될 가능성이 높다.","자산의 원가를 신뢰성 있게 측정할 수 있다."],"result":"기업회계기준서는 이 경우에만 무형자산을 인식하며, 장부금액 측정 방법과 공시 사항을 정하고 있다.","effects":[]},{"t":"def","term":"분리가능성","text":"자산의 분리가능성은 그 자산을 임대·매각·교환·분배할 수 있는 것을 뜻하며, 분리가능하지 않아도 계약상 권리 등 다른 방법으로 식별할 수 있으면 식별가능하다."},{"t":"vs","title":"식별가능성과 영업권","cols":[{"name":"무형자산","items":["무형자산의 정의에서 식별가능성을 요구하는 것은 영업권과 구별하기 위해서이다."]},{"name":"영업권","items":["개별적으로 식별해 인식할 수 없는 자산에서 발생하는 미래 경제적 효익을 나타낸다."]}]},{"t":"table","title":"통제와 경제적 효익","head":["항목","내용"],"rows":[["자원에 대한 통제","지식재산으로부터 미래의 경제적 효익을 배타적으로 얻고 제3자의 접근을 제한할 수 있는 경우를 말하며, 이는 법적 권리에서 나오는 것이 일반적이다."],["법적 집행가능성","다른 방법으로도 미래 경제적 효익을 통제할 수 있으므로 권리의 법적 집행가능성은 통제의 필요조건이 아니다."],["미래 경제적 효익","제품의 매출이나 용역수익, 원가절감 또는 자산 사용에 따른 기타 효익의 형태로 발생하며, 자산으로 인식하려면 이를 객관적으로 측정할 수 있어야 한다."]]}],"29":[{"t":"table","title":"무형자산 상각","head":["항목","내용"],"rows":[["상각 기간","지식재산은 경제적 효익을 제공할 것으로 추정되는 기간에 체계적으로 상각해야 하며 그 기간은 20년을 초과해서는 안 된다."],["상각의 효과","지식재산의 상각은 비용으로 인정되어 당기순이익을 줄이고 납세금액을 줄어들게 만든다."],["상각 시점","상각은 자산이 사용 가능한 때부터 시작하고, 매각예정으로 분류되는 날과 재무상태표에서 제거되는 날 중 이른 날에 중지한다."],["상각방법","정액법, 체감잔액법, 생산량비례법이 있으며, 소비 형태를 신뢰성 있게 결정할 수 없는 경우에는 정액법을 사용한다."],["상각액","일반적으로 당기손익으로 인식하지만, 미래 경제적 효익이 다른 자산의 생산에 소모되면 그 상각액은 다른 자산의 장부금액에 포함한다."]]},{"t":"def","term":"내용연수가 비한정인 무형자산","text":"상각하지 않고 회수가능액과 장부금액을 비교해 손상검사를 수행하며, 회수가능액을 초과하는 장부금액은 손상차손으로 인식한다."},{"t":"tree","title":"잔존가치와 검토","root":"내용연수가 유한한 지식재산","branches":[["잔존가치","내용연수 종료 시점에 제3자가 구입하기로 한 약정이 있거나 활성시장이 있어 잔존가치를 결정할 수 있고 존재 가능성이 높은 경우를 제외하고는 영(0)으로 본다."],["잔존가치 검토","적어도 매 회계연도 말에 검토하며, 잔존가치의 변동은 회계추정의 변경으로 처리한다."],["상각기간과 방법","적어도 매 회계연도 말에 검토하며, 예상 내용연수나 소비 형태가 달라지면 변경하고 이는 회계추정의 변경으로 처리한다."]]}],"30":[{"t":"vs","title":"라이선스 대가의 회계","cols":[{"name":"지불한 대가","items":["지식재산권 라이선스로 지불한 대가는 라이선시 기업이 비용으로 처리한다."]},{"name":"수취한 대가","items":["라이선스로 수취한 대가는 라이선스가 사업 목적 범위에 있으면 영업매출에 더해진다."]}]},{"t":"vs","title":"양도 시 손익","cols":[{"name":"취득금액보다 높게 양도","items":["양도이익을 계상한다."]},{"name":"취득금액보다 낮게 양도","items":["양도손실을 계상한다."]}]},{"t":"table","title":"무형자산 취득","head":["취득 방법","원가"],"rows":[["개별 취득","구입 가격과 자산을 의도한 목적에 사용할 수 있도록 준비하는 데 직접 관련되는 원가로 구성된다."],["사업결합","취득원가는 취득일 공정가치로 하며, 피취득자가 사업결합 전에 인식했는지와 관계없이 영업권과 분리해 별도 자산으로 인식한다. · 피취득자가 진행 중인 연구·개발 프로젝트는 자산의 정의를 충족하고 분리 가능하거나 계약상·법적 권리에서 발생하면 무형자산의 정의를 충족한다."],["자산교환","교환거래에 상업적 실질이 결여되었거나 두 자산의 공정가치를 신뢰성 있게 측정할 수 없는 경우를 제외하고 공정가치로 측정한다."],["내부 창출","미래 경제적 효익을 창출할 식별가능한 자산의 존재 시점을 파악하기 어렵고 원가를 신뢰성 있게 결정하기 어려워 인식 기준 충족 평가가 쉽지 않다. · 내부 프로젝트를 연구 단계와 개발 단계로 구분할 수 없는 경우 그 프로젝트에서 발생한 지출은 모두 연구 단계에서 발생한 것으로 본다."]]}],"31":[{"t":"def","term":"공정가치","text":"국제회계기준서상 공정가치는 측정일 시점에 시장 참여자 간 정상거래에서 자산을 매도로 수취하거나 부채를 이전으로 지급해야 할 금액(유출 가격)이다."},{"t":"vs","title":"원가모형과 재평가모형","cols":[{"name":"원가모형","items":["최초 인식 후 무형자산의 장부금액을 원가에서 상각누계액과 손상차손누계액을 차감한 금액으로 한다."]},{"name":"재평가모형","items":["재평가일의 공정가치에서 이후의 상각누계액과 손상차손누계액을 차감한 금액을 장부금액으로 하며, 이때 공정가치는 활성시장을 기초로 측정한다.","특허권이나 상표처럼 성격상 독특한 지식재산은 활성시장이 존재할 수 없어 재평가모형 적용이 어렵다.","무형자산을 선택적으로 재평가하거나 서로 다른 기준일의 금액이 혼재되는 것을 막기 위해 같은 분류 내의 무형자산 항목들은 동시에 재평가한다."]}]},{"t":"vs","title":"재평가 결과의 처리","cols":[{"name":"장부금액 증가","items":["증가액은 기타포괄손익으로 인식해 재평가잉여금으로 자본에 가산하되, 이전에 당기손익으로 인식한 재평가감소 해당액은 한도로 당기손익으로 인식한다."]},{"name":"장부금액 감소","items":["감소액은 당기손익으로 인식하되, 해당 자산의 재평가잉여금 잔액이 있으면 그 한도로 기타포괄손익에서 먼저 줄인다."]}]}],"32":[{"t":"def","term":"지식재산(IP) 금융","text":"지식재산의 창출·사업화·활용 과정에서 지식재산을 기반으로 투자, 융자, 보증 등의 자금을 공급하는 금융 활동이다.","ex":["기술기반 기업에서는 특허기술이 핵심 자산이므로, 전통적인 부동산 담보 평가에서 벗어나 기술 및 지식재산 중심의 평가에 기반한 지식재산 금융이 중요해지고 있다.","기술금융은 기술 개발에서 사업화까지 전 과정의 자금 접근성을 높이기 위해 기술과 기업에 기초해 금융 기능을 제공하는 활동이며, 지식재산 금융은 그 진화된 기업금융의 한 형태이다."]},{"t":"table","title":"지식재산 금융의 유형","head":["유형","제공 기관"],"rows":[["지식재산 담보대출","산업은행·기업은행 등 은행"],["지식재산 보증","신용보증기금·기술보증기금·서울신용보증재단"],["지식재산 투자","벤처캐피털 등 투자전문 금융회사"]]},{"t":"vs","title":"창의자본형과 창의기업형","cols":[{"name":"창의자본형","items":["지식재산 자체를 수익창출 수단으로 한다.","IP투자는 IP 자체에 대한 투자가 가능하다.","IP담보는 원칙적으로 지식재산 자체를 기초로 하는 창의자본형 금융이어야 하나 일부 금융권은 기업의 재무건전성도 함께 고려하며, 점진적으로 창의자본형으로 가고 있다."]},{"name":"창의기업형","items":["지식재산을 매개로 금융서비스를 제공한다.","IP투자는 IP를 보유한 기업에 대한 투자가 가능하다.","IP보증은 지식재산 보유기업의 신용을 고려한 창의기업형 금융이다."]}]}],"33":[{"t":"table","title":"IP금융 정책 연혁","head":["시기","내용"],"rows":[["1997년~2001년","기술담보시범사업은 지식재산권 가치평가액의 80%를 대출하고 회수불가 시 은행 손실비용의 90%를 정부가 보전하는 사업이었으나 정부 재정 부담이 커서 종료되었다."],["2006년","특허청은 모태펀드 특허계정에 550억 원을 출자하면서 특허기술 사업화 등 정책적 투자대상에 투자하는 IP투자펀드를 조성했다."],["1996년부터","시행한 발명의 평가지원 사업을 기술보증기금과 연계해 IP보증 서비스를 시작했다."],["2013년","신용보증기금과 협약해 특허기술가치평가 연계보증을 시행했다."]]},{"t":"cause","title":"IP금융 활성화","causes":["기술개발 이후 사업화 단계에서 금융 공급이 부족하면 생산·판매와 고용창출로 이어지지 않는다.","금융이 부동산·재무 중심에서 기술·지식재산 중심의 평가로 이동하고 있다."],"result":"IP금융 활성화가 필요하다.","effects":[]}],"34":[{"t":"vs","title":"지식재산의 법령상 범위","cols":[{"name":"포괄적 개념","items":["지식재산 기본법과 기술의 이전 및 사업화 촉진에 관한 법률은 권리화되지 않은 정보·지식까지 포함하는 포괄적 개념으로 정의한다."]},{"name":"권리화된 지식재산","items":["동산·채권 등의 담보에 관한 법률은 권리화된 지식재산을 대상으로 한다."]}]},{"t":"table","title":"지식재산 기본법의 정의","head":["용어","정의"],"rows":[["지식재산","인간의 창조적 활동이나 경험 등으로 창출·발견된 지식·정보·기술, 사상이나 감정의 표현, 영업·물건의 표시, 생물의 품종·유전자원, 그 밖에 재산적 가치가 실현될 수 있는 무형적인 것"],["신지식재산","경제·사회·문화의 변화나 과학기술의 발전에 따라 새로운 분야에서 출현하는 지식재산"],["지식재산권","법령·조약 등에 따라 인정되거나 보호되는 지식재산에 관한 권리"]]},{"t":"tree","title":"지식재산 담보","root":"지식재산 담보","branches":[["지식재산권담보권","동산·채권 등의 담보에 관한 법률상 담보약정에 따라 질권을 설정할 수 있는 지식재산권을 목적으로 해당 개별 법률에 따라 등록한 담보권이다."],["공동담보","지식재산권자가 동일한 채권 담보를 위해 둘 이상의 지식재산권을 담보로 제공하는 경우 특허원부·저작권등록부 등 공적 장부에 담보권을 등록할 수 있으며, 담보 대상 권리는 등록부를 관장하는 기관이 동일해야 한다."],["제정","부동산 담보능력이 부족한 중소기업이 동산·채권 등으로 자금을 조달하도록 동산·채권 등의 담보에 관한 법률이 2010년 6월 제정되어 2012년 6월 시행되었고, 지식재산권 등 모든 자산에 담보권 설정이 가능해졌다."],["정부 시책","지식재산 기본법에 따라 정부는 지식재산의 이전·거래·사업화를 촉진하기 위해 창업 활성화, 수요자·공급자 연계, 가치 증대와 자본 조성, 유동화 제도 정비, 투자·융자·신탁·보증·보험 활성화 방안을 포함한 시책을 마련해야 한다."]]}],"35":[{"t":"def","term":"IP금융의 제공","text":"지식재산 금융은 기업의 R&D, 창업, 사업화, 성장, 성숙의 사이클에서 단계별로 IP보증, IP담보대출, IP투자 등 각 유형별 금융기관을 통해 중소·벤처기업에 제공된다."},{"t":"vs","title":"기술신용대출과 IP담보대출","cols":[{"name":"기술신용대출","items":["2014년 본격 도입된 기술금융 방식으로 재무정보 등 신용평가에 기술력 평가를 추가로 고려해 신용도 판단 예측의 정확성을 높인다.","기술신용평가기관(TCB)에 평가를 의뢰해 대출 여부를 결정한다.","신용에 기반한 대출이다."]},{"name":"IP담보대출","items":["기업이 보유한 자산으로서의 지식재산권을 담보로 융자받는다.","사업화 이후 어느 정도 매출이 발생하는 기업이 보유한 지식재산권을 담보로 은행에서 융자받는 방식이며, 은행이 IP가치평가기관에 평가를 의뢰해 그 결과를 토대로 대출한다."]}]},{"t":"flow","title":"IP담보대출 절차","steps":["은행과 신청기업 간에 근질권설정계약을 체결","특허청 등록원부에 설정등록","질권의 설정등록 시 유질계약을 등록원인으로 등록하고 채무기업의 처분승낙서를 첨부","특약사항으로 처분승낙서 내용과 공동담보 목록을 포함"]}],"36":[{"t":"cause","title":"IP담보대출 회수","causes":["채무불이행 시 담보IP 처분에 높은 전문성이 필요하다.","국내 IP 거래시장이 활성화되지 않아 처분 가능성이 낮다."],"result":"금융권이 IP를 담보로 취급하기를 어려워한다.","effects":[]},{"t":"vs","title":"회수지원펀드와 회수지원기구","cols":[{"name":"과거 회수지원펀드","items":["모태펀드와 은행의 공동출자로 조성되어 채무불이행이 발생하면 매입 시점에 담보IP를 재평가해 매입하는 구조였다.","채무불이행 이후 사후 평가로 지원 여부를 정하는 한계가 있었다."]},{"name":"회수지원기구","items":["정부와 금융기관이 공동으로 마련했다.","IP담보대출 취급 시점부터 회수지원 여부를 결정해 금융권의 적극적 IP담보대출 취급을 가능하게 했다."]}]},{"t":"table","title":"IP담보대출 실적","head":["항목","내용"],"rows":[["신규 대출액","2017년 1,655억 원에서 2022년 9,156억 원으로 늘었고 취급은행은 국책·시중은행에서 주요 지방은행까지 확산되었다."],["금리","2~3% 내외가 다수로 평균 4~5%대인 신용대출 금리보다 낮다."],["대출 기업","대출 기업의 77.7%가 신용등급 BB+ 이하의 저신용기업이다."]]}],"37":[{"t":"def","term":"지식재산 보증","text":"주로 물적 담보가 부족한 초기기업을 대상으로 보증기관이 지식재산 평가를 근거로 보증서를 발급하고 은행이 이를 기반으로 대출하는 방식이며, 채무불이행 시 보증기관이 리스크를 부담하는 관주도 금융이다."},{"t":"table","title":"IP 보증상품","head":["기관","상품"],"rows":[["신용보증기금·서울신용보증재단","IP 우대보증은 한국발명진흥회 특허평가분석시스템을 연계해 B등급 이상 특허를 보유한 기업에 보증한다."],["기술보증기금","IP패스트보증은 기술보증기금 특허평가시스템을 활용한다."],["운영","국내에서 지식재산 평가 기반 보증상품은 신용보증기금, 기술보증기금, 서울신용보증재단을 중심으로 운영되며, 지식재산 창출·거래·사업화·활용촉진 단계별로 상품이 설계되어 있다."]]},{"t":"cause","title":"지식재산 보증 규모","causes":["2017년 4,930억 원에서 2022년 8,781억 원으로 점진적으로 늘었다."],"result":"보증비율 우대(90~100%)와 보증료 감면(0.2~0.5%p) 혜택이 주어진다.","effects":[]}]};
