(window.TNQ=window.TNQ||[]).push({"terms":{"합작투자":{"d":"목표한 사업을 위해 참여 기업들이 지식재산을 공유하고 협력하는 투자 관계로 조인트 벤처라고도 합니다.","r":[]},"자기자본":{"d":"조달한 자본 가운데 상환 의무가 없는 자본으로 법인에서는 주주나 출자자가 투자한 금액입니다.","r":["타인자본"]},"타인자본":{"d":"주주나 출자자 투자 이외에 타인에게서 조달하는 자금으로 갚아야 할 의무가 있습니다.","r":["자기자본"]},"자산실사":{"d":"매입 대상 기업이 소유하거나 쓰는 자산, 특히 지식재산의 상태를 사전에 조사하는 절차입니다.","r":[]},"라이선서":{"d":"라이선스 계약에서 지식재산의 사용 권한을 허락해 주는 쪽입니다.","r":["라이선시"]},"라이선시":{"d":"라이선스 계약에서 지식재산의 사용 권한을 허락받는 쪽입니다.","r":["라이선서"]},"크로스 라이선스":{"d":"둘 이상의 기업이 각자의 지식재산권을 상대방이 실시하도록 서로 허여하는 계약입니다.","r":[]},"재실시권":{"d":"실시권자가 제3자에게 다시 실시를 허락하는 권리로 권리자 동의 없이는 설정할 수 없습니다.","r":[]},"로열티공제법":{"d":"대상 IP를 보유하지 못해 라이선스받는다고 가정하고 절약되는 로열티의 현재가치로 가치를 추정하는 방법입니다.","r":["소득접근법","시장접근법"]},"소득접근법":{"d":"대상 자산이 경제적 수명 동안 낼 이익을 추정해 할인율로 현재가치로 환산하는 평가 방법입니다.","r":["할인현금흐름"]},"비용접근법":{"d":"같은 효익의 자산을 새로 개발하거나 구입하는 데 드는 원가를 추정해 가치를 정하는 평가 방법입니다.","r":[]},"시장접근법":{"d":"같거나 비슷한 자산이 시장에서 거래된 가격을 근거로 상대적 가치를 정하는 평가 방법입니다.","r":[]},"할인현금흐름":{"d":"미래의 잉여현금흐름을 할인율로 나누어 현재가치로 바꾸어 합산하는 방식입니다.","r":["소득접근법"]},"이용률":{"d":"사업제품의 여러 기술 구성요소 가운데 평가 대상 IP가 보호하는 기술의 비중입니다.","r":[]},"무형자산":{"d":"물리적 형체가 없으며 식별 가능하고 기업이 통제하며 미래 경제적 효익을 가져오는 자산입니다.","r":["영업권"]},"영업권":{"d":"개별적으로 식별해 인식할 수 없는 자산에서 발생하는 미래 경제적 효익을 나타내는 회계상 항목입니다.","r":["무형자산"]},"잔존가치":{"d":"내용연수가 끝나는 시점에 자산에 남아 있을 것으로 보는 가치로 보통 영(0)으로 봅니다.","r":[]},"손상차손":{"d":"자산의 장부금액이 회수가능액을 넘을 때 그 초과액을 비용으로 인식하는 손실입니다.","r":[]},"재평가모형":{"d":"재평가일의 공정가치에서 이후 상각누계액과 손상차손누계액을 뺀 금액을 장부금액으로 삼는 회계 처리 방법입니다.","r":[]},"공정가치":{"d":"측정일에 시장 참여자 사이의 정상거래에서 자산을 팔 때 받을 금액으로 보는 가치입니다.","r":[]},"IP담보대출":{"d":"기업이 보유한 지식재산권을 담보로 은행에서 융자받는 방식입니다.","r":[]},"창의자본형":{"d":"지식재산 자체를 수익 창출 수단으로 삼는 지식재산 금융의 유형입니다.","r":["창의기업형"]},"창의기업형":{"d":"지식재산을 매개로 하되 지식재산을 보유한 기업의 신용을 고려해 금융서비스를 제공하는 유형입니다.","r":["창의자본형"]},"근질권":{"d":"장래에 생길 불특정 채권을 담보하려고 일정 한도까지 설정하는 질권입니다.","r":[]}},"notes":{"1단계: 라이선서 입장에서 라이선싱 필요성과 사업화 전략 검토, 대상 선정, 지식재산 마케팅 등 기술 마케팅의 준비와 실시":"1단계는 라이선서가 필요성과 사업화 전략을 검토하고 대상 선정, 지식재산 마케팅 같은 기술 마케팅을 준비·실시하는 단계입니다.","2014년 본격 도입된 기술금융 방식으로 재무정보 등 신용평가에 기술력 평가를 추가로 고려해 신용도 판단 예측의 정확성을 높인다.":"기술신용대출은 2014년 본격 도입된 방식으로 재무정보 중심 신용평가에 기술력 평가를 더해 신용도 예측의 정확성을 높입니다.","2017년 1,655억 원에서 2022년 9,156억 원으로 늘었고 취급은행은 국책·시중은행에서 주요 지방은행까지 확산되었다.":"신규 대출액이 2017년 1,655억 원에서 2022년 9,156억 원으로 늘었고 취급은행도 지방은행까지 확산됐습니다.","2017년 4,930억 원에서 2022년 8,781억 원으로 점진적으로 늘었다.":"보증 규모는 2017년 4,930억 원에서 2022년 8,781억 원으로 서서히 불었습니다.","2~3% 내외가 다수로 평균 4~5%대인 신용대출 금리보다 낮다.":"IP담보대출 금리는 대체로 2~3%라 평균 4~5%대인 신용대출보다 낮습니다.","2단계: 라이선시 발굴·선정 뒤 기술료 등 거래 조건을 협상하고 협상 결과를 계약서로 작성해 체결":"2단계는 라이선시를 찾아 고른 뒤 기술료 등 조건을 협상해 계약서로 체결하는 단계입니다.","3단계: 필요한 신고·승인, 계약 실행, 기술료 수령 등 사후관리와 계약 완료":"3단계는 필요한 신고·승인과 계약 실행, 기술료 수령 같은 사후관리를 하고 계약을 마무리하는 단계입니다.","Avery Dennison은 경쟁사의 강력한 특허 때문에 힘을 못 쓰던 사업의 특허를 처분하고, 그 수입을 성장 중인 사업에 재투자했다.":"Avery Dennison은 경쟁사 특허에 막힌 사업의 특허를 팔고 그 돈을 성장 사업에 다시 투자했습니다.","Canon은 잉크젯 카트리지, 용지 등 프린터 소모품 관련 기술을 모두 특허화하는 유지 전략으로 프린터 시장의 우위를 지켰다.":"Canon은 잉크젯 카트리지와 용지 등 소모품 기술까지 전부 특허로 묶어 프린터 시장 우위를 지켰습니다.","IP금융 활성화가 필요하다.":"이런 흐름에서 IP금융 활성화가 필요합니다.","IP담보는 원칙적으로 지식재산 자체를 기초로 하는 창의자본형 금융이어야 하나 일부 금융권은 기업의 재무건전성도 함께 고려하며, 점진적으로 창의자본형으로 가고 있다.":"IP담보는 원래 지식재산 자체를 보는 창의자본형이어야 하나 현실에서는 기업 재무도 같이 보고 점차 그쪽으로 옮겨 갑니다.","IP담보대출 취급 시점부터 회수지원 여부를 결정해 금융권의 적극적 IP담보대출 취급을 가능하게 했다.":"대출 취급 시점부터 회수지원 여부를 정해 금융권이 IP담보대출을 적극 하도록 했습니다.","IP를 평가대상으로 하며 두 평가는 원칙과 방법론이 상당 부분 유사하다.":"IP가치평가는 IP를 평가 대상으로 하며 기술가치평가와 원칙·방법론이 대체로 비슷합니다.","IP보증은 지식재산 보유기업의 신용을 고려한 창의기업형 금융이다.":"IP보증은 지식재산을 가진 기업의 신용을 보는 창의기업형입니다.","IP 없이 기술·노하우만 평가하지 않는다.":"IP가치평가는 IP 없는 기술·노하우만을 평가하지는 않습니다.","IP 없이 기술·노하우만 평가할 수도 있다.":"기술가치평가는 IP 없이 기술이나 노하우만도 평가할 수 있습니다.","IP 우대보증은 한국발명진흥회 특허평가분석시스템을 연계해 B등급 이상 특허를 보유한 기업에 보증한다.":"신용보증기금 등의 IP 우대보증은 한국발명진흥회 평가를 이용해 B등급 이상 특허 보유 기업에 보증합니다.","IP투자는 IP를 보유한 기업에 대한 투자가 가능하다.":"창의기업형 IP투자는 IP를 가진 기업에 투자합니다.","IP투자는 IP 자체에 대한 투자가 가능하다.":"창의자본형 IP투자는 IP 자체에 투자할 수 있습니다.","IP패스트보증은 기술보증기금 특허평가시스템을 활용한다.":"기술보증기금의 IP패스트보증은 자체 특허평가시스템을 이용합니다.","M&A가 기업의 개별 이전이 아닌 포괄적 이전이다.":"M&A는 개별 이전이 아니라 기업을 통째로 넘기는 포괄적 이전입니다.","TI는 Amati Communications를 인수해 25개의 DSL 특허를 얻었고, 이 특허가 DSL 기술표준으로 채택되어 시장을 선도했다.":"TI는 Amati를 사서 얻은 DSL 특허 25개가 기술표준이 된 덕에 시장을 앞서 나갔습니다.","각종 절차와 규제에서 생기는 비용이 진입장벽이 되며, 사업화에 필요한 인허가·규제도 유무형의 비용으로 작용한다.":"절차와 규제에 드는 비용, 그리고 사업화에 필요한 인허가가 모두 진입장벽 역할을 합니다.","감소액은 당기손익으로 인식하되, 해당 자산의 재평가잉여금 잔액이 있으면 그 한도로 기타포괄손익에서 먼저 줄인다.":"재평가로 금액이 내리면 당기손익으로 처리하되, 쌓아 둔 재평가잉여금이 있으면 그만큼은 기타포괄손익에서 먼저 줄입니다.","개량기술을 서로 일정 조건으로 자유롭게 실시하게 하거나 공유하거나, 별도 라이선스를 체결할 의무 또는 협상 우선권을 주는 조항을 둘 수 있다.":"양쪽이 개량기술을 서로 쓰게 하거나 공유하거나, 별도 라이선스 체결 의무나 협상 우선권을 주는 조항을 둘 수 있습니다.","개별적으로 식별해 인식할 수 없는 자산에서 발생하는 미래 경제적 효익을 나타낸다.":"영업권은 개별로 식별해 인식할 수 없는 자산에서 나오는 미래 경제적 효익입니다.","개별 지식재산보다 기업 전체의 가치를 평가하는 것이 합리적이다.":"기업 단위로 사고팔기 때문에 지식재산 하나하나보다 전체 기업 가치를 보는 편이 맞습니다.","거래사례비교법과 경매가 있다.":"시장접근법의 구체적 방법은 거래사례비교법과 경매입니다.","경영실적이 나쁘거나 비전이 없는 사업의 특허, 주력 사업과 관련성이 낮은 특허 등을 타사에 판매해 수익 기회를 만드는 전략이다.":"처분 전략은 실적이 나쁘거나 주력과 거리가 먼 특허를 남에게 팔아 수익 기회를 만드는 전략입니다.","경제·사회·문화의 변화나 과학기술의 발전에 따라 새로운 분야에서 출현하는 지식재산":"신지식재산은 경제·사회·문화 변화나 과학기술 발전으로 새 분야에서 나타나는 지식재산입니다.","경제적 가치가 동등하면 보통 무상으로 계약한다.":"서로 가치가 같으면 보통 무상으로 계약합니다.","계약기간의 순이익을 기술 기여도에 따라 배분한다.":"순이익 배분 방식은 계약기간의 순이익을 기술 기여도대로 나눕니다.","계약 당사자, 실시허락의 대상 기술, 실시권의 세 가지이며, 실시료는 법적 필수요소가 아니다.":"법적으로 꼭 필요한 요소는 당사자, 대상 기술, 실시권이며 실시료가 없어도 계약은 성립합니다.","계약 시 한 번에 지불하는 고정 금액이며, 계약 체결 이후 특정 시점에 분납으로 나누어 받는 방식도 포함한다.":"정액 기술료는 계약 때 한 번에 내는 고정 금액이고 특정 시점에 나눠 받는 분납 방식도 포함합니다.","계약에 의한 실시권은 사적 자치의 원칙에 따라 기간을 한정하거나 실시 지역, 실시 제품 또는 형태를 한정해 설정할 수 있다.":"기간, 지역, 제품 형태를 한정해 설정할 수 있는 것은 계약 자유의 원칙 덕분입니다.","계약에 의한 합의만으로 효력이 발생한다.":"통상실시권은 계약 합의만으로 효력이 생깁니다.","계약자유의 원칙에 따라 전용실시인지 통상실시인지를 가리지 않고 합의만으로 성립하며 제3자의 동의나 행정청의 허가·등록이 필요 없다.":"계약자유의 원칙상 전용이든 통상이든 합의만으로 성립하고 제3자 동의나 행정청 허가·등록이 필요 없습니다.","공동 개발·마케팅으로 라이선스 대상 기술이 산업 표준이 되도록 노력할 수 있고 실질적 표준 기술이 되게 할 수도 있다.":"함께 개발·마케팅하면 라이선스 기술을 산업 표준이나 사실상 표준 기술로 키울 수 있습니다.","과거 지식재산권을 침해한 라이선시에게 손해액을 배상받는 경우나 라이선시 재정이 불투명한 경우에 쓰일 수 있다.":"이미 침해한 사람에게 손해액을 받아야 하거나 상대 재정이 미심쩍을 때 단기 라이선스가 맞습니다.","관할 법원, 적용 법률, 분쟁 해결 절차 등을 명확히 규정해 법적 불확실성을 줄인다.":"국제 계약에서는 관할 법원, 적용 법률, 절차를 분명히 적어 법적 불확실성을 줄입니다.","교환거래에 상업적 실질이 결여되었거나 두 자산의 공정가치를 신뢰성 있게 측정할 수 없는 경우를 제외하고 공정가치로 측정한다.":"교환으로 얻은 자산은 상업적 실질이 없거나 공정가치를 믿을 만하게 잴 수 없을 때만 빼고 공정가치로 측정합니다.","구입 가격과 자산을 의도한 목적에 사용할 수 있도록 준비하는 데 직접 관련되는 원가로 구성된다.":"개별 취득 원가는 구입 가격과 의도한 목적에 쓰도록 준비하는 데 직접 든 원가입니다.","국내 IP 거래시장이 활성화되지 않아 처분 가능성이 낮다.":"국내 IP 거래시장이 작아 처분이 잘 되지 않습니다.","국내에서 지식재산 평가 기반 보증상품은 신용보증기금, 기술보증기금, 서울신용보증재단을 중심으로 운영되며, 지식재산 창출·거래·사업화·활용촉진 단계별로 상품이 설계되어 있다.":"평가 기반 보증상품은 신용보증기금, 기술보증기금, 서울신용보증재단 중심으로 창출·거래·사업화·활용촉진 단계에서 운영됩니다.","국내외에서 출원 중이거나 등록된 발명, 상표, 영업비밀, 배치설계가 포함된다.":"가치평가 대상은 발명, 상표, 영업비밀, 배치설계이며 국내외에서 출원 중이거나 등록된 것이 해당합니다.","국제 라이선스 계약이나 기술도입 계약을 체결할 때는 주무관청이나 공정거래위원회에 소정 사항을 신고해야 하는 경우도 있다.":"국제 라이선스·기술도입 계약은 경우에 따라 주무관청이나 공정거래위원회에 신고해야 합니다.","국제회계기준서상 공정가치는 측정일 시점에 시장 참여자 간 정상거래에서 자산을 매도로 수취하거나 부채를 이전으로 지급해야 할 금액(유출 가격)이다.":"국제회계기준의 공정가치는 측정일에 시장 참여자 사이 정상거래에서 자산을 팔 때 받을 금액, 곧 유출 가격입니다.","규모의 경제와 범위의 경제를 실현하고 기술과 자원의 시너지를 극대화해 효율성을 높일 수 있다.":"규모와 범위의 경제를 이루고 기술·자원 시너지를 키워 효율을 높일 수 있습니다.","그 범위 안에서 권리자도 실시할 수 없고 중첩되는 라이선스를 제3자에게 줄 수 없다.":"독점을 주면 그 범위 안에서는 권리자 자신도 실시할 수 없고 제3자에게 겹치는 라이선스도 못 줍니다.","글로벌 기업 간에 체결이 늘고 있다.":"크로스 라이선스는 요즘 세계적인 기업들 사이에서 점점 더 많이 맺어집니다.","금융권이 IP를 담보로 취급하기를 어려워한다.":"그러니 금융권이 IP 담보를 꺼립니다.","금융이 부동산·재무 중심에서 기술·지식재산 중심의 평가로 이동하고 있다.":"금융의 평가 기준이 부동산·재무에서 기술·지식재산으로 옮겨 가는 중입니다.","기술개발 이후 사업화 단계에서 금융 공급이 부족하면 생산·판매와 고용창출로 이어지지 않는다.":"연구개발이 끝나도 사업화 자금이 모자라면 생산·판매와 고용으로 이어지지 못합니다.","기술금융은 기술 개발에서 사업화까지 전 과정의 자금 접근성을 높이기 위해 기술과 기업에 기초해 금융 기능을 제공하는 활동이며, 지식재산 금융은 그 진화된 기업금융의 한 형태이다.":"기술금융은 기술과 기업을 보고 개발부터 사업화까지 자금 길을 넓히는 활동이고 IP금융은 거기서 발전한 것입니다.","기술기반 기업에서는 특허기술이 핵심 자산이므로, 전통적인 부동산 담보 평가에서 벗어나 기술 및 지식재산 중심의 평가에 기반한 지식재산 금융이 중요해지고 있다.":"기술기반 기업은 특허가 핵심 자산이라 부동산 담보 평가를 벗어나 기술·지식재산 중심 평가로 하는 IP금융이 중요해지고 있습니다.","기술담보시범사업은 지식재산권 가치평가액의 80%를 대출하고 회수불가 시 은행 손실비용의 90%를 정부가 보전하는 사업이었으나 정부 재정 부담이 커서 종료되었다.":"가치평가액의 80%를 빌려주고 못 받으면 은행 손실의 90%를 정부가 메워 주는 사업이었으나 정부 부담이 커서 끝났습니다.","기술 또는 지식재산을 개발하는 데 든 제반 개발비용을 기초로 경과기간의 가치증감분을 차감해 산정하는 방법이다.":"비용접근법은 개발에 든 비용에서 경과기간의 가치 증감분을 빼서 산정합니다.","기술 보유자가 필요하지 않거나 부가가치를 창출하기 어려운 지식재산을 타 기업에 전달하는 방법으로, 무형자산을 처분하여 현금·주식·영업권 등을 확보할 수 있다.":"매각은 필요 없거나 부가가치를 못 내는 지식재산을 남에게 넘기는 방법으로 현금·주식·영업권 등을 받고 무형자산을 처분합니다.","기술수명주기가 있어 오래 유지하기 어렵다.":"기술창업의 아이템은 기술수명주기가 있어 오래 유지하기 어렵습니다.","기술시장의 로열티율 시장데이터를 쓰는 점":"시장접근법과 닮은 점은 기술시장의 로열티율 시장데이터를 쓴다는 점입니다.","기술신용평가기관(TCB)에 평가를 의뢰해 대출 여부를 결정한다.":"대출 여부는 TCB의 평가 결과를 받아 정합니다.","기술요소법, 다기간 초과이익법, 증분수익법, 잔여가치법, 실물옵션법이 있다.":"이 다섯 기법, 곧 기술요소법과 다기간 초과이익법, 증분수익법, 잔여가치법, 실물옵션법이 소득접근법에 속합니다.","기술을 직접 제공하지 않고도 수익을 얻는다.":"라이선서는 기술을 직접 공급하지 않아도 수익을 얻습니다.","기술을 평가대상으로 한다는 점이 주된 차이이다.":"기술가치평가는 기술 자체를 평가 대상으로 삼는다는 점이 주된 차이입니다.","기술이전 후 미실시에 대한 페널티로 지급한다.":"미실시 기술료는 이전받고도 실시하지 않는 데 대한 벌칙으로 냅니다.","기술적 과제를 해결하고 사업적 비전을 향상시키는 수단":"기술 도입자에게 라이선싱은 기술 과제를 풀고 사업 비전을 높이는 수단입니다.","기술제공 내용과 조건을 법적 구속력 있는 문서로 보존하고 계약 이행·해석의 기준이자 분쟁 해결의 기초 근거가 된다.":"계약서는 제공 내용과 조건을 구속력 있는 문서로 남겨 이행·해석의 기준이자 분쟁 해결의 근거가 됩니다.","기술창업의 기본 절차는 사업 아이템을 정하고 객관적 검증을 거쳐 실현 가능한 계획을 세운 뒤 창업을 실현하는 과정이다.":"기술창업은 아이템을 정하고 객관적으로 검증한 뒤 실현 가능한 계획으로 창업을 실현하는 순서입니다.","기술창업의 아이디어는 혁신성과 실현 가능성을 갖추어야 하며, 지식재산권 확보가 가능한 아이디어가 경쟁우위와 투자 유치에 좋다.":"아이디어는 혁신적이고 실현 가능해야 하며, 지식재산권을 확보할 수 있어야 경쟁우위와 투자 유치에 좋습니다.","기술창업의 초기 자본은 주로 엔젤 투자자, 벤처캐피털, 정부 지원 프로그램을 통해 조달하는 것이 일반적이다.":"초기 자본은 대개 엔젤 투자자, 벤처캐피털, 정부 지원 프로그램에서 조달합니다.","기업 M&A는 기술적 경쟁 우위나 시장 점유율을 높이기 위해 상대 기업의 지식재산을 획득하는 것이 주된 목적이 될 수 있다.":"기업 M&A의 주된 목적은 상대 회사의 지식재산을 얻어 기술 우위나 점유율을 높이는 데 있을 수 있습니다.","기업가치 산정 시 무형자산으로 반영된다.":"기업 가치를 매길 때 지식재산은 무형자산으로 계산에 들어갑니다.","기업의 가치가 모든 자산의 수익획득 능력에 의존한다는 가정에서 출발해, IP를 활용한 사업의 미래 기대수익을 예측하고 이를 현재가치화하며 가장 현실적이라는 장점이 있다.":"소득접근법은 기업 가치가 모든 자산의 수익 능력에 달려 있다는 가정에서 출발해 IP 활용 사업의 미래 수익을 현재가치로 바꾸는 방법입니다.","기업이 보유한 자산으로서의 지식재산권을 담보로 융자받는다.":"IP담보대출은 기업이 가진 지식재산권을 담보로 융자받는 것입니다.","기업이 평가대상 IP를 보유하지 못해 제3자에게서 라이선스받는 경우를 가정해, 경제적 수명기간의 로열티의 현재가치를 기술가치로 추정하는 방법이다.":"로열티공제법은 IP가 없어 제3자에게서 라이선스받는다고 가정하고 수명 동안 로열티의 현재가치를 기술가치로 추정합니다.","기업회계기준서는 이 경우에만 무형자산을 인식하며, 장부금액 측정 방법과 공시 사항을 정하고 있다.":"기업회계기준서는 이 두 요건을 갖출 때만 무형자산으로 인식하고 장부금액 측정과 공시 사항을 정합니다.","기존 기술가치평가 모형은 기술과 지식재산권을 구분하지 않아 지식재산에 초점을 맞춘 평가에는 한계가 있다.":"옛 모형은 기술과 지식재산권을 가르지 않아서 지식재산 평가에는 맞지 않는 면이 있습니다.","기존 기업이나 연구기관이 개발한 기술을 이전받아 독립 회사를 세우는 형태로 기술적 리스크가 상대적으로 낮다.":"스핀오프 창업은 남이 개발한 기술을 이전받아 독립 회사를 세우는 형태로 기술적 위험이 비교적 낮습니다.","기준 로열티율에 개별 IP의 기술적·권리적·시장적·사업적 특성을 포함한 조정계수를 반영하고, 전체 제품 중 평가대상 IP가 차지하는 비중까지 고려해 추정한다.":"기준 로열티율에 기술적·권리적·시장적·사업적 특성의 조정계수를 반영하고 전체 제품 중 IP 비중까지 따져 최종 로열티율을 추정합니다.","기회비용 관점에서 평가대상 IP의 가치를 추정하는 접근법이며 평가대상 IP가 경제적 이익을 창출할 수 있다는 충분한 근거가 필요하다.":"이 방법은 기회비용 관점이어서 대상 IP가 경제적 이익을 낼 수 있다는 충분한 근거가 필요합니다.","낮은 성장률이나 이윤 축소 같은 당면 문제를 해결하기 위해 12~18개월 정도 걸리는 방안을 제시하며 이윤 제고와 수입 증대를 목표로 한다. 특허위치에서 경쟁력이 약한 부분을 강화하고 자사 보유특허를 상호 라이선싱이나 로열티 획득 수단으로 활용한다.":"유지 전략은 낮은 성장률이나 이윤 축소 같은 당면 문제를 12~18개월 걸릴 방안으로 풀며 이윤과 수입을 늘리려 합니다.","내부 프로젝트를 연구 단계와 개발 단계로 구분할 수 없는 경우 그 프로젝트에서 발생한 지출은 모두 연구 단계에서 발생한 것으로 본다.":"연구와 개발 단계를 나눌 수 없으면 그 프로젝트의 지출은 모두 연구 단계에서 생긴 것으로 봅니다.","내용연수 종료 시점에 제3자가 구입하기로 한 약정이 있거나 활성시장이 있어 잔존가치를 결정할 수 있고 존재 가능성이 높은 경우를 제외하고는 영(0)으로 본다.":"잔존가치는 제3자의 구입 약정이나 활성시장이 있어 결정 가능하고 존재 가능성이 높을 때를 빼고는 영(0)으로 봅니다.","다른 공유자의 동의를 받지 않으면 제3자에게 실시권을 허락할 수 없다.":"공유특허권자는 다른 공유자의 동의 없이는 제3자에게 실시권을 허락할 수 없습니다.","다른 기업과의 특허 소송에 드는 비용·인력·시간을 절약할 수 있다.":"특허 소송에 드는 비용·인력·시간을 아낄 수 있습니다.","다른 기업에 바로 판매하는 것은 리스크가 가장 낮은 방법이지만 높은 리스크를 구매자에게 넘기는 것이므로 상대적으로 수익은 낮아진다.":"바로 파는 것은 위험이 가장 낮지만 큰 위험을 구매자에게 넘기는 것이어서 상대적으로 수익이 적습니다.","다른 기업의 지식재산을 획득해 독점적 기술·제품을 보유하고 경쟁사보다 우월한 위치를 차지하려는 동기이다.":"독점적 이익 동기는 남의 지식재산을 얻어 독점 기술·제품으로 경쟁사보다 우월해지려는 것입니다.","다른 방법으로도 미래 경제적 효익을 통제할 수 있으므로 권리의 법적 집행가능성은 통제의 필요조건이 아니다.":"다른 방법으로도 효익을 통제할 수 있어서 법적 집행가능성이 통제의 필요조건은 아닙니다.","담보 대출, 특허 소송 등 적극적 권리행사를 통한 수익화":"다른 갈래는 담보 대출이나 특허 소송처럼 권리를 적극 행사해 돈을 버는 수익화입니다.","당사자의 자유의사에 의한 거래":"다른 요건은 거래가 당사자의 자유의사로 이루어졌다는 점입니다.","대상 IP가 법적 논란이나 침해 분쟁에 휘말리지 않았는지 확인해 매입 후 법적 리스크를 최소화해야 한다.":"대상 IP가 분쟁에 휘말리지 않았는지 보아 매입 후 법적 리스크를 최소화합니다.","대상 IP기술과 비교해 동일하거나 유사한 기술거래 로열티를 초기값으로 하고, 비교기술 간 속성 차이를 반영해 기본 로열티를 조정한다.":"비슷한 기술 거래의 로열티를 초기값으로 삼고 기술 속성 차이를 반영해 기본 로열티를 조정합니다.","대상 발명 등을 활용한 사업의 경제성을 분석하는 것이며, 사업화 주체가 정해졌다면 그 주체의 개발·인적·마케팅 등 사업화 역량 분석도 포함한다.":"사업성은 사업의 경제성을 보는 요소이며, 사업화 주체가 정해졌다면 그 주체의 개발·인력·마케팅 역량도 분석합니다.","대상 발명 등의 기술적 유용성과 경쟁력 수준을 분석하는 것으로 완성도·구현 가능성, 활용성·확장성, 비교우위·경쟁성 분석을 포함한다.":"기술성은 기술적 유용성과 경쟁력을 보는 요소로 완성도·구현 가능성, 활용성·확장성, 비교우위를 분석합니다.","대상 발명 등이 권리로서 적절히 보호되는지 분석하는 것으로 선행기술 대비 권리 안정성, 권리 보호강도, 제품·서비스 적용 여부 분석을 포함한다.":"권리성은 권리로 잘 보호되는지 보는 요소로 권리 안정성, 보호강도, 제품·서비스 적용 여부를 분석합니다.","대상의 현재 또는 장래의 경제적 가치를 가액·등급 또는 점수 등으로 표시하는 것이다.":"발명 등의 평가는 대상의 현재·장래 경제적 가치를 금액·등급·점수로 나타내는 것입니다.","대상이 이미 개발과 인적·물적 구조를 갖추고 있어 스타트업 창업보다 리스크가 낮고 사업화 기간이 단축되며 통제력을 유지할 수 있다.":"이미 개발과 인력·설비를 갖춘 회사를 사는 것이어서 창업보다 위험이 낮고 사업화가 빠르며 통제력도 유지됩니다.","대상제품의 미래 수요예측이 선행되어야 하고 신제품은 관련 데이터가 없어 작성이 더 어려우므로, 관련 업계 종사자가 상식적으로 납득 가능한 수준에서 세워야 한다.":"미래 수요예측이 먼저이고 신제품은 자료가 없어 더 어려우니 업계 종사자가 상식적으로 납득할 수준에서 세웁니다.","대상 지식재산의 권리범위를 확정해 그 범위 안의 기술을 대상 기술로 인식하며, 권리로 보호되지 않는 기술적 노하우는 구분한다.":"권리범위를 확정해 그 안의 기술을 대상 기술로 삼고 권리로 보호되지 않는 노하우는 따로 구분합니다.","대체로 제조업, 전문서비스업, 지식문화사업 분야의 창업을 뜻하지만 해당 기업군을 정의하는 일관된 용어는 없다.":"이 창업이 어느 업종인지 딱 잘라 말하는 통일된 용어는 없고 흔히 제조·전문서비스·지식문화 분야를 가리킵니다.","대체의 경제 원리에 기초해 동일한 경제적 효익의 지식재산을 개발·구입하는 원가를 추정하는 방법으로, 기술개발비용·재생산원가·대체원가 정보가 필요하다.":"비용접근법은 같은 효익의 지식재산을 새로 개발·구입하는 원가를 추정하며 개발비용·재생산원가·대체원가 정보가 필요합니다.","대출 기업의 77.7%가 신용등급 BB+ 이하의 저신용기업이다.":"대출을 받은 기업 가운데 77.7%가 신용등급 BB+ 이하의 낮은 신용 기업입니다.","대통령령으로 정하며, 평가기관은 평가 시 그 기준을 준수하여야 한다.":"평가 기준은 대통령령으로 정하고 평가기관은 평가할 때 이를 지켜야 합니다.","대학이나 연구기관이 보유한 기술의 상용화를 위해 설립된 회사로 기술이전과 사업화를 전문적으로 지원한다.":"기술지주회사는 대학·연구기관 기술의 상용화를 위해 설립되어 기술이전과 사업화를 전문으로 돕습니다.","동산·채권 등의 담보에 관한 법률상 담보약정에 따라 질권을 설정할 수 있는 지식재산권을 목적으로 해당 개별 법률에 따라 등록한 담보권이다.":"지식재산권담보권은 동산채권담보법상 담보약정으로 질권을 설정할 수 있는 지식재산권에 대해 개별 법률로 등록한 담보권입니다.","동산·채권 등의 담보에 관한 법률은 권리화된 지식재산을 대상으로 한다.":"동산채권담보법이 다루는 지식재산은 이미 권리로 만들어진 것에 한합니다.","동업자는 창업자와 함께 금전·현물·기술을 투자하고 사업부문별 역할을 맡아 그 과실을 분배받는 사람으로 창업자 다음으로 중요한 구성원이다.":"동업자는 돈·현물·기술을 함께 투자하고 부문별 역할을 맡아 성과를 나눠 갖는, 창업자 다음으로 중요한 구성원입니다.","둘 이상의 기업이 각자의 지식재산권을 상대방에게 실시하도록 허여한다.":"크로스 라이선스는 둘 이상의 기업이 서로에게 지식재산권의 실시를 허락하는 계약입니다.","둘 이상의 기업이 각자의 지식재산을 공유하거나 상호 협력하여 새로운 시너지를 창출하기 위해 체결하며, 제휴에 따른 위험과 보상은 상호 협력 분야로 제한된다.":"전략적 제휴는 둘 이상의 기업이 지식재산을 나누거나 협력해 시너지를 내려고 맺고, 위험과 보상은 협력 분야에 따라 달라집니다.","등록된 IP의 보호기간이 곧 만료될 가능성이 있으면 가치를 재평가하거나 만료를 기다려 실시하는 방안을 검토한다.":"보호기간이 곧 끝날 가능성이 있으면 가치를 다시 평가하거나 만료를 기다려 실시하는 방안을 따집니다.","라이선서가 기술자료를 작성·송부할 경우 그 기술자료에 대한 비밀유지 의무를 라이선시에게 주지시켜야 한다.":"라이선서가 기술자료를 보낼 때는 그 자료의 비밀유지 의무를 라이선시에게 알려야 합니다.","라이선서는 여러 사람에게 허여해 실시료 수입을 극대화하고 라이선시의 개량기술도 이익으로 얻는다.":"비독점이면 여러 곳에 주어 실시료를 늘리고 라이선시가 개량한 기술의 이익도 가져올 수 있습니다.","라이선스로 수취한 대가는 라이선스가 사업 목적 범위에 있으면 영업매출에 더해진다.":"사업 목적 범위 안의 라이선스로 받은 대가는 영업매출에 합산합니다.","라이선스를 주는 자가 라이선서(licensor)이고 라이선스를 받는 자가 라이선시(licensee)이다.":"허락해 주는 쪽이 라이선서(licensor), 허락받는 쪽이 라이선시(licensee)입니다.","라이선스를 타인에게 주는 것":"라이선싱 아웃은 내 권리에 대한 라이선스를 남에게 주는 쪽입니다.","라이선스받은 기술로 만든 제품·서비스의 판매에 따라 지속적으로 지불하며 통상 총매출액의 일정 비율로 계산한다.":"경상 기술료는 라이선스 기술 제품의 판매에 따라 계속 내며 보통 총매출액의 일정 비율입니다.","라이선시가 개량한 기술에 일정한 권리를 갖는 쪽이 유리하다.":"라이선서로서는 상대가 개량한 기술에도 권리를 갖는 쪽이 이롭습니다.","라이선시가 사업을 포기하거나 재무적 어려움을 겪으면 라이선서 입장에서는 위험 부담이 있다.":"라이선시가 사업을 접거나 재정이 어려워지면 라이선서는 위험을 부담합니다.","라이선시의 시장점유율과 제조·판매능력을 면밀히 조사해야 한다.":"독점을 주기 전에 상대의 점유율과 제조·판매 능력을 꼼꼼히 조사해야 합니다.","라이선시의 실시에 따른 실시료를 징수해 수익을 얻으며, 경상실시료로 합의하면 라이선시의 매출이 늘수록 실시료 수입도 늘어난다.":"라이선서는 실시료를 받는데 경상실시료로 합의하면 라이선시 매출이 늘수록 수입도 늘어납니다.","라이선시의 영업을 통해 새 시장에 진입할 수 있다.":"라이선서는 라이선시의 영업망으로 새 시장에 들어갈 수 있습니다.","라이선싱 활동은 관련 시장 확대와 기술개발 가속으로 기업 가치를 높이는 개방형 혁신의 일종으로 볼 수 있다.":"라이선싱은 시장을 키우고 기술개발을 앞당겨 기업 가치를 높이므로 개방형 혁신의 일종입니다.","로열티 수익과 세금 비용 예측을 기준으로 현금유입과 현금유출의 차액을 연도별로 추정하며, 특허권의 경우 대상기간은 권리 잔존기간 이내에서 정한다.":"로열티 수익과 세금 비용을 기준으로 현금 유입과 유출의 차이를 연도별로 추정하고 특허권은 권리 잔존기간 안에서 기간을 정합니다.","로열티 수익 흐름을 현재가치로 환원하는 점":"로열티공제법이 수익접근법과 닮은 점은 로열티 수익 흐름을 현재가치로 환원한다는 점입니다.","로열티율은 추정 매출액에 곱해 로열티 수입을 추정하며, 세금을 제외한 세후 로열티 수입을 현재가치화해 연도별로 합하면 IP가치가 산출된다.":"로열티율을 추정 매출액에 곱해 로열티 수입을 구하고 세후 수입을 현재가치로 바꿔 연도별로 합하면 IP가치가 나옵니다.","리스크가 이전되는 만큼 잠재수익도 라이선시에게 비례적으로 이전된다.":"위험이 넘어가는 만큼 잠재 수익도 라이선시에게 비례해 넘어갑니다.","리스크 대부분이 제품 개발·제조·마케팅을 맡는 라이선시(기술도입자)에게 이전된다.":"위험은 개발·제조·마케팅을 맡는 라이선시에게 옮겨 갑니다.","리스크와 수익을 소유자 간에 나누므로 스타트업 설립이나 기업매수보다 수익은 낮아진다.":"위험도 이익도 소유자끼리 나누니 설립이나 기업 매수보다 수익은 낮아집니다.","리스크와 잠재수익이 모두 가장 높다.":"스타트업 창업은 위험과 잠재 수익이 함께 가장 높습니다.","많은 가정과 변수가 개입되어 산정 결과의 변동성이 크다.":"가정과 변수가 많이 개입해 결과의 변동성이 큽니다.","매입 대상 기업이 다른 회사와 공유하는 IP는 구매자가 소유하고 라이선스를 판매자에게 줄지, 그 반대로 할지 명확히 합의해야 한다.":"다른 회사와 공유하는 IP는 구매자가 소유하고 판매자에게 라이선스를 줄지, 반대로 할지 분명히 합의해야 합니다.","매입 대상 기업이 소유하거나 사용하는 지식재산은 자산실사(due diligence)를 통해 조사해야 한다.":"사려는 회사의 지식재산 상태는 자산실사(due diligence)로 미리 조사합니다.","매출이 적어 기술 수준과 성장성 같은 무형의 가치를 평가받아야 하지만 이를 위한 시스템이 취약하다.":"초기 기업은 매출이 작아 기술 수준이나 성장성 같은 보이지 않는 가치로 평가받는데, 그 평가 체계가 약합니다.","모태펀드와 은행의 공동출자로 조성되어 채무불이행이 발생하면 매입 시점에 담보IP를 재평가해 매입하는 구조였다.":"옛 회수지원펀드는 모태펀드와 은행이 함께 출자해 채무불이행 시 매입 시점에 담보 IP를 재평가해 사들이는 구조였습니다.","목표한 사업을 위해 참여 기업들이 지식재산을 공유하고 공동 목표를 위해 협력하는 투자 관계로, 조인트 벤처라고도 불린다.":"합작투자는 참여 기업이 지식재산을 나누고 공동 목표로 협력하는 관계로 조인트 벤처라고도 합니다.","무형자산을 선택적으로 재평가하거나 서로 다른 기준일의 금액이 혼재되는 것을 막기 위해 같은 분류 내의 무형자산 항목들은 동시에 재평가한다.":"선택적 재평가나 기준일이 다른 금액이 섞이는 것을 막으려고 같은 분류의 무형자산은 동시에 재평가합니다.","무형자산의 정의에서 식별가능성을 요구하는 것은 영업권과 구별하기 위해서이다.":"식별가능성 요건은 무형자산을 영업권과 가르기 위한 것입니다.","미래 경제적 효익을 창출할 식별가능한 자산의 존재 시점을 파악하기 어렵고 원가를 신뢰성 있게 결정하기 어려워 인식 기준 충족 평가가 쉽지 않다.":"내부 창출은 자산의 존재 시점과 원가를 정하기 어려워 인식 기준을 충족하는지 평가하기 쉽지 않습니다.","미래 현금흐름의 순현재가치에서 IP가 공헌한 상대적 비중인 IP기여도를 고려해야 한다.":"현재가치로 바꾼 미래 현금흐름 중 IP가 기여한 비율, 곧 IP기여도를 따로 따져야 합니다.","법령·조약 등에 따라 인정되거나 보호되는 지식재산에 관한 권리":"지식재산권은 법령·조약 등으로 인정·보호되는 지식재산에 관한 권리입니다.","벤처캐피털 등 투자전문 금융회사":"IP 투자는 벤처캐피털 같은 투자전문 금융회사가 맡습니다.","보유 지식재산은 대상 기업에 대한 중요한 실사 항목 중 하나이다.":"대상 기업의 보유 지식재산은 실사에서 살펴볼 항목 가운데 하나입니다.","보증비율 우대(90~100%)와 보증료 감면(0.2~0.5%p) 혜택이 주어진다.":"우대 혜택은 보증비율 90~100%와 보증료 0.2~0.5%p 감면입니다.","보통 선급금을 적게, 경상 실시료는 높게 설정하며, 라이선시가 스타트업이나 작은 기업일 때 양측에 유리할 수 있다.":"장기 라이선스는 선급금을 적게, 경상 실시료를 높게 잡는 일이 많아 스타트업이나 작은 기업이 라이선시이면 양측에 유리할 수 있습니다.","부동산 담보능력이 부족한 중소기업이 동산·채권 등으로 자금을 조달하도록 동산·채권 등의 담보에 관한 법률이 2010년 6월 제정되어 2012년 6월 시행되었고, 지식재산권 등 모든 자산에 담보권 설정이 가능해졌다.":"부동산 담보가 부족한 중소기업이 동산·채권으로 자금을 조달하도록 이 법이 2010년 6월 제정되어 2012년 6월 시행됐습니다.","비교 가능한 동일·유사사례를 찾기 쉽지 않고, 자리를 잡은 기업의 매출 추정에 초점을 맞춰 기술기반 스타트업의 특허 평가에는 한계가 있다.":"비교 가능한 사례를 찾기 쉽지 않고 안정된 기업 매출 추정에 맞춰져 있어 기술기반 스타트업의 특허 평가에는 한계가 있습니다.","비교 가능한 지식재산의 활발한 거래시장":"시장접근법의 요건 하나는 비교 가능한 지식재산의 활발한 거래시장입니다.","사례가 없거나 매우 적으면 직접 산출하기보다 업종별 거래사례 로열티 통계에서 적정범위를 산출하고, 이것도 부족하면 상관행법 로열티 통계를 적용할 수 있다.":"사례가 없거나 적으면 업종별 거래사례 통계로 적정 범위를 구하고, 이마저 부족하면 상관행법 통계를 쓸 수 있습니다.","사업성 있는 아이템을 포착하고 기술을 사업화할 역량이 중요한데, 많은 기업이 이 역량 확보에 실패한다.":"좋은 아이템을 잡아 기술을 사업으로 만드는 힘이 핵심인데, 이 능력을 갖추지 못해 실패하는 기업이 많습니다.","사업실행 단계: 선정된 창업 아이템의 사업화를 위해 회사 설립, 공장 설립, 조직·인력 확보, 경영관리를 진행":"사업실행 단계는 회사·공장 설립, 조직·인력 확보, 경영관리로 아이템을 사업화하는 단계입니다.","사업화 이후 어느 정도 매출이 발생하는 기업이 보유한 지식재산권을 담보로 은행에서 융자받는 방식이며, 은행이 IP가치평가기관에 평가를 의뢰해 그 결과를 토대로 대출한다.":"사업화 후 어느 정도 매출이 나는 기업의 지식재산권을 담보로 은행이 융자하며, 은행이 IP가치평가기관에 의뢰한 결과를 활용합니다.","사용 범위, 사용 기간, 지불 방식, 지식재산의 유지·보호에 관한 사항이 포함되며 양측의 협상으로 정한다.":"계약 조건에는 사용 범위·기간, 지불 방식, 지식재산의 유지·보호 사항이 들어가며 양측 협상으로 정합니다.","상각은 자산이 사용 가능한 때부터 시작하고, 매각예정으로 분류되는 날과 재무상태표에서 제거되는 날 중 이른 날에 중지한다.":"사용 가능한 때 상각이 시작되고, 매각예정 분류일과 재무상태표 제거일 중 먼저 오는 날 멈춥니다.","상각하지 않고 회수가능액과 장부금액을 비교해 손상검사를 수행하며, 회수가능액을 초과하는 장부금액은 손상차손으로 인식한다.":"내용연수가 비한정이면 상각 대신 회수가능액과 장부금액을 비교해 손상검사를 하고, 장부금액이 더 크면 손상차손을 인식합니다.","상당한 투자가 요구되어 잠재 수익이 감소하고, 기업문화 융합의 어려움과 원치 않는 자산·부채 인수 및 돌발채무의 부담이 따를 수 있다.":"큰 투자가 필요해 수익 여지가 줄고, 기업문화 융합이 어렵고 원치 않는 자산·부채나 돌발채무까지 떠안을 수 있습니다.","상장기업의 자기자본 할인율은 무위험이자율에 시장수익률과 무위험이자율의 차이에 위험척도(β)를 곱한 값을 더해 산출한다.":"자기자본 할인율은 안전한 이자율에다 시장 초과수익률과 위험척도(β)의 곱을 더해 계산합니다.","상호 허여하는 권리의 가치 차이가 있으면 해당 차액을 지불하고 사용하기도 한다.":"가치 차이가 있으면 차액을 내고 쓰기도 합니다.","새로운 스타트업을 설립하는 경우 리스크와 잠재수익이 모두 가장 높다.":"새 스타트업은 위험도 크고 잠재 수익도 가장 큰 방법입니다.","새 시장 진입에 따른 설비 투자 비용과 사업 불확실성을 부담하게 된다.":"라이선시는 새 시장 진입에 드는 설비 투자 비용과 사업 불확실성을 부담합니다.","생계형 창업은 제외하는 것이 일반적이다.":"생계를 위한 창업은 보통 지식기술창업에서 뺍니다.","설정·등록되면 그 범위 안에서는 특허권자도 특허발명을 실시할 수 없고 전용실시권자가 실시할 권리를 독점한다.":"설정·등록되면 그 범위에서는 특허권자도 실시할 수 없고 전용실시권자만 독점합니다.","손익계산서로 현금흐름을 추정할 때 감가상각비·지급이자·배당은 비용이지만 실제 현금유출이 없을 수 있어, 순이익에 감가상각비를 더해 실제 생성되는 현금총액을 계산한다.":"감가상각비·지급이자·배당은 비용이지만 실제 현금유출이 없을 수 있어 순이익에 감가상각비를 더해 실제 현금흐름을 구합니다.","수익성에 근거하지 않아 미래의 수익창출능력을 반영하지 못해, 주로 소득접근법이나 시장접근법의 보완자료로 쓴다.":"수익성에 근거하지 않아 미래 수익 창출 능력을 담지 못하므로 소득·시장접근법의 보완 자료로 주로 씁니다.","수익을 창출할 수 있는 명확하고 실현 가능한 모델로, 가격 책정, 판매 전략, 수익 구조 등을 포함한다.":"비즈니스 모델은 수익을 낼 수 있는 분명하고 실현 가능한 틀로 가격, 판매 전략, 수익 구조를 포함합니다.","스타트업 설립, 기존 법인 매수, 합작투자 기업 설립":"지식재산 사업화의 첫 갈래는 새 회사를 세우거나, 있는 법인을 사거나, 합작 기업을 세우는 일입니다.","스타트업이 아이디어 개발부터 시장 진입까지 직접 하기 어려우면 기술을 일정 수준까지 개발한 후 지식재산권을 대기업에 매각하며 기술을 지도하는 것을 사업 전략으로 취할 수 있다.":"스타트업이 시장 진입까지 직접 하기 어려우면 일정 수준까지 개발한 뒤 지식재산권을 대기업에 팔고 기술을 지도하는 길이 있습니다.","스톡옵션제도로 인재를 영입하고, B2G 사업 확대를 위해 NET·NEP 인증제도를 활용하는 것도 전략이 될 수 있다.":"스톡옵션으로 인재를 모으고 B2G 사업 확대를 위해 NET·NEP 인증제도를 쓰는 것도 전략입니다.","시장규모와 예상매출액, IP의 경제적 수명, 로열티율, 현금흐름, 할인율이 있다.":"입력해야 하는 값은 시장규모와 예상매출, 경제적 수명, 로열티율, 현금흐름, 할인율입니다.","시장 내 경쟁자를 제거하거나 약화시키기 위해 M&A를 하면 시장점유율을 높이고 가격 책정 등에서 우위를 점할 수 있다.":"경쟁자를 없애거나 약화시키는 M&A는 점유율을 높이고 가격 책정에서도 우위를 줍니다.","시장에서 적용되는 산출 방식과 요율을 이용한다.":"시장접근법은 시장에서 쓰이는 산출 방식과 요율을 가져다 기술료를 정합니다.","시장환경과 시장경쟁 분석으로 적용제품이나 서비스의 시장경쟁력을 분석하는 것으로 시장규모·성장성, 시장 점유율 확보 가능성 분석을 포함한다.":"시장성은 시장환경과 경쟁을 분석하는 요소로 시장규모·성장성과 점유율 확보 가능성을 봅니다.","시행한 발명의 평가지원 사업을 기술보증기금과 연계해 IP보증 서비스를 시작했다.":"발명 평가지원 사업을 기술보증기금과 이어 IP보증 서비스를 시작한 것입니다.","신기술을 보유한 기업을 인수하면 내부 기술 개발에 드는 시간과 비용을 절감하고 빠르게 변하는 시장에서 혁신을 주도할 수 있다.":"신기술 보유 기업을 사면 내부 개발의 시간과 비용을 아끼고 빠른 시장에서 혁신을 이끌 수 있습니다.","신용보증기금과 협약해 특허기술가치평가 연계보증을 시행했다.":"신용보증기금과 협약하여 특허기술가치평가를 보증과 연결해 시행했습니다.","신용보증기금·기술보증기금·서울신용보증재단":"IP 보증은 신용보증기금, 기술보증기금, 서울신용보증재단이 맡습니다.","실무상 매출액이나 현금흐름을 전제할 수밖에 없어, 기술가치평가의 기본 원칙과 평가방법이 준용되되 지식재산권의 특수성을 고려해야 한다.":"실무에서는 매출이나 현금흐름이 전제되므로 기술가치평가의 원칙을 준용하되 지식재산권의 특수성을 반영해야 합니다.","실시권의 상호 허여에 관한 계약이다.":"Cross License Agreement는 실시권을 서로 허여하는 계약입니다.","실시권자는 권리자의 동의 없이는 자신의 실시권을 양도하거나 재실시권을 설정할 수 없다.":"실시권자가 마음대로 실시권을 넘기거나 재실시를 허락하는 것은 권리자 동의 없이는 안 됩니다.","실시·사용 능력, 협력관계 지속을 위한 신뢰성, 사업영역과 전략에서의 상충 가능성 등을 고려한다.":"라이선시를 고를 때는 실시 능력, 협력을 이어 갈 신뢰성, 사업영역·전략의 충돌 가능성을 봅니다.","실시 수량에 최소 수량을 정하는 것은 라이선서 입장에서 최소한의 실시료를 확보하는 기능을 하므로 최저 실시료를 정하는 것과 같다.":"최소 실시 수량을 정하면 라이선서가 최소한의 실시료를 확보하므로 최저 실시료를 정한 것과 같은 기능을 합니다.","아이템 사업화를 가능하게 하는 핵심 기술인력을 확보하지 못하면 창업 자체가 불가능할 수 있다.":"사업화를 이끌 핵심 기술인력을 못 구하면 창업 자체가 불가능할 수 있습니다.","앞서 설명한 사업화 유형들보다 리스크가 낮다.":"라이선싱은 앞의 사업화 유형들보다 위험이 낮습니다.","양 당사자의 위험을 줄일 수 있다.":"비독점 라이선스는 양 당사자의 위험을 줄입니다.","양자 간 계약으로 체결되며 라이선시만 권리를 쓸 수 있다.":"폐쇄형 라이선스는 두 당사자 사이 계약이라 라이선시만 권리를 씁니다.","업계 평균 매출규모를 기본으로 하되, 사업지배계수가 높을수록 최대시장규모에 접근하는 것으로, 높지 않으면 업계 평균 매출액에 접근하는 것으로 설정한다.":"업계 평균 매출을 기본으로 하되 사업지배계수가 높을수록 최대시장규모에, 높지 않으면 업계 평균에 가깝게 잡습니다.","여러 라이선시에게 같은 지식재산 사용을 허용한다.":"비독점 라이선스는 여러 라이선시에게 같은 지식재산을 쓰게 합니다.","연도별 잉여현금흐름을 (1+할인율)의 연차 거듭제곱으로 나눈 값을 합산해 IP로 인한 사업가치를 구한다.":"연차마다 (1+할인율)의 거듭제곱으로 현금흐름을 줄여 합치면 IP가 만드는 사업가치가 됩니다.","예비창업패키지, 초기창업패키지, 청년창업사관학교, TIPS 같은 정부 창업지원 매칭자금으로 초기 창업자금을 확보하는 형태도 있다.":"정부가 주는 매칭자금으로는 예비창업패키지, 초기창업패키지, 청년창업사관학교, TIPS가 있어 초기 자금 확보에 쓰입니다.","원재료 공급부터 판매까지 장악하는 수직적 합병은 협상·조정·커뮤니케이션 비용과 광고·포장 비용을 줄일 수 있다.":"원재료부터 판매까지 잡는 수직적 합병은 협상·조정·소통 비용과 광고·포장 비용을 줄입니다.","유사한 지식재산이 거래된 가격을 조사해 평가대상의 가치를 산정하며, 매매 사례가 없거나 비교 가능성이 없으면 적용할 수 없다.":"시장접근법은 비슷한 지식재산의 거래 가격으로 가치를 구하므로 매매 사례나 비교 가능성이 없으면 쓸 수 없습니다.","유용한 특허를 가진 경우 크로스 라이선스로 서로 사용하게 할 수 있고, 제3자 권리 침해 시에도 공동 대응으로 분쟁 대응 역량을 강화할 수 있다.":"라이선시도 유용한 특허가 있으면 크로스 라이선스로 서로 쓰게 하고, 제3자 침해에는 공동 대응할 수 있습니다.","은행과 신청기업 간에 근질권설정계약을 체결":"IP담보대출은 먼저 은행과 신청기업이 근질권설정계약을 맺는 데서 시작합니다.","이미 사업화된 IP보다 사업성이 검증되지 않은 신기술 IP에서 리스크가 커 달리 적용해야 한다.":"이미 사업화된 IP보다 사업성이 검증되지 않은 신기술 IP의 위험이 커서 할인율을 달리 적용합니다.","인간의 창조적 활동이나 경험 등으로 창출·발견된 지식·정보·기술, 사상이나 감정의 표현, 영업·물건의 표시, 생물의 품종·유전자원, 그 밖에 재산적 가치가 실현될 수 있는 무형적인 것":"지식재산은 창조적 활동이나 경험으로 나온 지식·정보·기술, 표현, 표시, 품종·유전자원, 그 밖의 재산적 가치 있는 것을 말합니다.","인수 대상 기업의 전문인력과 인재를 자사로 흡수해 인적 자원의 질을 높이고 핵심 역량을 강화할 수 있다.":"인수 대상의 전문인력을 흡수해 인적 자원의 질과 핵심 역량을 키울 수 있습니다.","일반적으로 당기손익으로 인식하지만, 미래 경제적 효익이 다른 자산의 생산에 소모되면 그 상각액은 다른 자산의 장부금액에 포함한다.":"상각액은 보통 당기손익으로 보지만 효익이 다른 자산의 생산에 소모되면 그 자산의 장부금액에 포함합니다.","일반적으로 소득접근법, 비용접근법, 시장접근법이 쓰이며, 로열티공제법은 소득접근법과 시장접근법을 결합한 방법으로 지식재산 금융 평가에 널리 활용된다.":"가치평가 방법은 소득·비용·시장접근법이 일반적이고, 로열티공제법은 소득접근법과 시장접근법을 합친 방법으로 지식재산 금융 평가에 널리 쓰입니다.","일정 조건 아래 공개되어 누구나 이용할 수 있다.":"개방형 라이선스는 일정 조건 아래 공개되어 누구나 이용할 수 있습니다.","자사 지식재산을 다른 기업에 이용 허가하여 수익을 창출하는 방법":"기술 보유자는 자기 지식재산을 다른 기업이 쓰게 허락해 수익을 얻습니다.","자산에서 발생하는 미래 경제적 효익이 기업에 유입될 가능성이 높다.":"무형자산 인식 요건 하나는 미래 경제적 효익이 기업에 들어올 가능성이 높다는 점입니다.","자산의 분리가능성은 그 자산을 임대·매각·교환·분배할 수 있는 것을 뜻하며, 분리가능하지 않아도 계약상 권리 등 다른 방법으로 식별할 수 있으면 식별가능하다.":"팔거나 빌려 줄 수 있으면 분리가능이고, 분리가 안 돼도 계약상 권리 등으로 가려낼 수 있으면 식별가능합니다.","자산의 원가를 신뢰성 있게 측정할 수 있다.":"다른 요건은 자산의 원가를 믿을 만하게 측정할 수 있다는 점입니다.","잠재수익도 라이선시에게 비례적으로 이전되어 라이선서의 수익은 줄어든다.":"잠재 수익이 라이선시 쪽으로도 넘어가 라이선서 수익은 줄어듭니다.","장래 현금흐름을 적절한 할인율로 나누어 현재가치를 산출하는 할인현금흐름(DCF)법이 기본적으로 적용된다.":"할인현금흐름(DCF)법은 먼 미래 돈을 할인율로 나눠 지금 가치로 바꾸는 기본 방법입니다.","재실시권 허락 권리를 라이선시에게 주는 경우에도 재실시권은 라이선서와 라이선시의 기존 계약 조건을 초과할 수 없다.":"재실시권을 허락할 권리를 받아도 기존 계약 조건을 넘는 재실시권은 줄 수 없습니다.","재평가일의 공정가치에서 이후의 상각누계액과 손상차손누계액을 차감한 금액을 장부금액으로 하며, 이때 공정가치는 활성시장을 기초로 측정한다.":"재평가모형은 재평가일 공정가치에서 이후 상각누계액·손상차손누계액을 뺀 금액을 장부금액으로 하고 공정가치는 활성시장 기준입니다.","적어도 매 회계연도 말에 검토하며, 예상 내용연수나 소비 형태가 달라지면 변경하고 이는 회계추정의 변경으로 처리한다.":"상각기간과 방법도 매 회계연도 말에 검토해 예상 내용연수나 소비 형태가 달라지면 바꾸고 회계추정의 변경으로 처리합니다.","적어도 매 회계연도 말에 검토하며, 잔존가치의 변동은 회계추정의 변경으로 처리한다.":"잔존가치는 매 회계연도 말에 검토하고 변동은 회계추정의 변경으로 처리합니다.","적절한 마케팅 기간이 주어진 뒤 이해관계가 없는 자발적 판매자와 구매자 사이에서 평가일 현재 자산이 교환될 추정 금액이다.":"시장가치는 충분히 알린 뒤 이해관계 없는 자발적 매도자와 매수자가 평가일에 자산을 교환할 추정 금액입니다.","접근법은 서로 다른 경제적 관점에 기반하므로 상이한 가치 결과를 낳을 수 있어 가치평가 제반 상황을 감안해 신중히 결정해야 한다.":"접근법마다 경제적 관점이 달라 결과도 달라질 수 있어 상황을 감안해 신중히 골라야 합니다.","정당한 권한자가 특허제품을 정당하게 유통했을 때 구매자에게 권리자가 침해를 주장할 수 없게 되는 것으로, 권리 소진 법리에 따른다.":"정당하게 유통된 특허제품을 산 사람에게 권리자가 침해를 주장할 수 없는 것은 권리 소진 법리에 따른 묵시적 라이선스입니다.","정부는 객관적 가치평가 촉진을 위해 지식재산 가치의 평가기법과 평가체계를 확립하고 이를 거래·금융 등에 활용하도록 지원해야 한다.":"지식재산 기본법에 따라 정부는 평가기법과 평가체계를 세우고 거래·금융에 활용하도록 도와야 합니다.","정부와 금융기관이 공동으로 마련했다.":"회수지원기구는 정부와 금융기관이 함께 만들었습니다.","정액법, 체감잔액법, 생산량비례법이 있으며, 소비 형태를 신뢰성 있게 결정할 수 없는 경우에는 정액법을 사용한다.":"상각방법에는 정액법, 체감잔액법, 생산량비례법이 있고 소비 형태를 믿을 만하게 정할 수 없으면 정액법을 씁니다.","제도적 검토 없이 사업을 시작하면 제품이 나와도 시장에 출시할 수 없는 문제가 생길 수 있으므로 법적 구조와 규제 준수 확인이 필요하다.":"제도를 검토하지 않고 시작하면 제품을 만들고도 출시를 못 할 수 있어 법적 구조와 규제 준수를 점검합니다.","제반요소가 객관적으로 결정된다면 이론적으로 가장 타당한 방법이다.":"요소가 객관적으로 정해진다면 이론상 가장 타당한 방법이라는 것이 소득접근법의 장점입니다.","제품 개발·제조·마케팅을 맡는 라이선시(기술도입자)에게 리스크 대부분이 이전된다.":"제품 개발·제조·마케팅을 맡는 라이선시가 위험 대부분을 떠안습니다.","제품라인 개발이나 신규 시장 확장 같은 장기 문제와 관련되며, 향후 18개월에서 5년의 경쟁 상황에 초점을 둔다. M&A로 새로운 시장의 특허를 획득해 그 시장에 성공적으로 진입할 수 있다.":"성장 전략은 장기 과제를 다루며 앞으로 18개월에서 5년의 경쟁 상황을 보고 M&A로 새 시장 특허를 확보합니다.","제품·서비스에 대가를 지급하고 구입하려는 고객 집단으로, 시장 가능성을 보고 제품을 개발하는 쪽이 기술 우수성만 믿고 개발하는 것보다 성공 가능성이 높다.":"시장은 대가를 내고 사 줄 고객 집단이라 시장 가능성을 보고 개발하는 쪽이 기술만 믿고 개발하는 쪽보다 성공 가능성이 큽니다.","제품수명주기, 기술진보속도, 경쟁기술 출현가능성 등을 종합해 추정하며, 특허인용관계를 활용한 기술순환주기(TCT)를 참고자료로 쓰기도 한다.":"경제적 수명은 제품수명주기, 기술진보속도, 경쟁기술 출현 가능성을 종합해 추정하며 기술순환주기(TCT)를 참고하기도 합니다.","제품을 구성하는 세부기술을 모두 나열해 각 비중을 분석한 뒤 평가 IP에 해당하는 세부기술을 체크해 산출하며, 비중은 원가, 소비자 구매 요인, 전문가의 정성적 평가 등이 될 수 있다.":"세부기술을 모두 늘어놓고 비중을 분석해 평가 IP에 해당하는 것만 체크해 산출하며 비중은 원가, 구매 요인, 전문가 판단 등으로 정합니다.","제품의 매출이나 용역수익, 원가절감 또는 자산 사용에 따른 기타 효익의 형태로 발생하며, 자산으로 인식하려면 이를 객관적으로 측정할 수 있어야 한다.":"효익은 매출·용역수익·원가절감 등으로 나타나며 자산으로 인식하려면 객관적으로 측정할 수 있어야 합니다.","조건 달성부 기술료라고도 하며, 라이선시가 특정 개발 단계나 성과 조건을 달성할 때마다 지불한다.":"마일스톤 기술료는 조건 달성부 기술료라고도 하며 특정 개발 단계나 성과 조건을 달성할 때마다 냅니다.","조달된 자본 중 상환 의무가 없는 자본으로, 법인기업에서는 주주나 출자자가 투자한 금액을 말한다.":"자기자본은 조달한 자본 가운데 갚을 의무가 없는 것으로 법인에서는 주주나 출자자의 투자금입니다.","주로 IT융합 분야의 콘텐츠·소프트웨어, 제조업 융합 분야, 지식 기반 서비스업이 포함된다.":"지식기술창업에는 주로 IT융합 콘텐츠·소프트웨어, 제조업 융합, 지식 기반 서비스업이 들어갑니다.","주로 물적 담보가 부족한 초기기업을 대상으로 보증기관이 지식재산 평가를 근거로 보증서를 발급하고 은행이 이를 기반으로 대출하는 방식이며, 채무불이행 시 보증기관이 리스크를 부담하는 관주도 금융이다.":"지식재산 보증은 물적 담보가 부족한 초기 기업을 위해 보증기관이 평가를 근거로 보증서를 내고 은행이 이를 바탕으로 대출하는 방식입니다.","주로 소프트웨어 분야에서 쓰이며, 오픈소스 소프트웨어는 자유롭게 이용·복제·재배포·수정할 수 있는 것이 특징이다.":"개방형은 소프트웨어에 많고, 오픈소스는 이용·복제·재배포·수정이 자유롭다는 특징이 있습니다.","중재, 조정, 법정 소송 등 양측이 합의한 방법으로 분쟁을 해결하게 한다.":"분쟁 해결 조항은 중재, 조정, 소송 중 양측이 합의한 방법을 정해 둡니다.","증가액은 기타포괄손익으로 인식해 재평가잉여금으로 자본에 가산하되, 이전에 당기손익으로 인식한 재평가감소 해당액은 한도로 당기손익으로 인식한다.":"재평가로 금액이 오르면 기타포괄손익에서 재평가잉여금으로 쌓되, 앞서 당기손익으로 처리한 감소분까지만 당기손익에 넣습니다.","지급이자의 비용인정에 따른 감세효과를 고려해 이자율×(1－법인세율)로 하고, 자기자본과 타인자본을 함께 쓰면 구성비로 가중평균해 가중평균 자본비용을 산출한다.":"타인자본 할인율은 이자 비용의 감세 효과를 반영해 이자율×(1－법인세율)로 하고, 두 자본을 함께 쓰면 구성비로 가중평균합니다.","지리적 다변화와 새 고객층 확보를 이루고 여러 시장에 리스크를 분산해 안정적 성장을 꾀할 수 있다.":"지역 다변화와 새 고객 확보로 여러 시장에 위험을 나눠 안정적으로 성장할 수 있습니다.","지식재산 가치평가는 통상 금액으로 결정받아 왔다.":"가치평가는 그동안 보통 금액으로 결과를 냈습니다.","지식재산 가치평가의 법적 근거가 명확해졌고, 특허청이 지정한 발명의 평가기관의 평가활동을 위한 자격제도 운영 가이드라인이 마련되었다.":"발명진흥법 개정으로 가치평가의 법적 근거가 분명해졌고 특허청이 지정한 평가기관의 자격제도 운영 가이드라인도 마련됐습니다.","지식재산 거래가 정체되어 왔다.":"그 결과 지식재산 거래가 오랫동안 정체되어 왔습니다.","지식재산 거래의 가치평가 결과는 기업의 재무상태표에 적절히 반영되어야 한다.":"거래의 가치평가 결과는 기업 재무상태표에 알맞게 반영되어야 합니다.","지식재산권 라이선스로 지불한 대가는 라이선시 기업이 비용으로 처리한다.":"라이선스를 받으며 낸 대가는 라이선시 기업이 비용으로 처리합니다.","지식재산권 소유자가 다른 개인이나 기업에 해당 권리를 사용할 수 있는 권한을 부여하는 계약이며, 권리 양도와는 다르다.":"IP 라이선싱은 소유자가 남에게 사용 권한을 주는 계약이며 권리를 넘기는 양도와는 다릅니다.","지식재산권은 기술적 능력을 외부에 증명하는 수단이 된다.":"지식재산권은 회사의 기술력을 밖에 증명하는 수단 구실을 합니다.","지식재산권자가 동일한 채권 담보를 위해 둘 이상의 지식재산권을 담보로 제공하는 경우 특허원부·저작권등록부 등 공적 장부에 담보권을 등록할 수 있으며, 담보 대상 권리는 등록부를 관장하는 기관이 동일해야 한다.":"같은 채권 담보를 위해 둘 이상의 지식재산권을 담보로 제공하면 특허원부·저작권등록부 같은 공적 장부에 담보권을 등록할 수 있습니다.","지식재산 금융은 기업의 R&D, 창업, 사업화, 성장, 성숙의 사이클에서 단계별로 IP보증, IP담보대출, IP투자 등 각 유형별 금융기관을 통해 중소·벤처기업에 제공된다.":"IP금융은 R&D, 창업, 사업화, 성장, 성숙의 단계마다 IP보증, IP담보대출, IP투자를 금융기관이 중소·벤처기업에 제공합니다.","지식재산 기본법과 기술의 이전 및 사업화 촉진에 관한 법률은 권리화되지 않은 정보·지식까지 포함하는 포괄적 개념으로 정의한다.":"지식재산 기본법과 기술이전법은 권리화되지 않은 정보·지식까지 아우르는 포괄적 개념으로 지식재산을 정의합니다.","지식재산 기본법에 따라 정부는 지식재산의 이전·거래·사업화를 촉진하기 위해 창업 활성화, 수요자·공급자 연계, 가치 증대와 자본 조성, 유동화 제도 정비, 투자·융자·신탁·보증·보험 활성화 방안을 포함한 시책을 마련해야 한다.":"정부는 지식재산 기본법에 따라 이전·거래·사업화를 촉진하려고 창업 활성화, 연계, 자본 조성, 유동화 제도 정비를 합니다.","지식재산으로부터 미래의 경제적 효익을 배타적으로 얻고 제3자의 접근을 제한할 수 있는 경우를 말하며, 이는 법적 권리에서 나오는 것이 일반적이다.":"통제는 미래의 경제적 효익을 배타적으로 얻고 제3자의 접근을 막을 수 있는 경우를 말하며 보통 법적 권리에서 나옵니다.","지식재산은 경제적 효익을 제공할 것으로 추정되는 기간에 체계적으로 상각해야 하며 그 기간은 20년을 초과해서는 안 된다.":"효익을 줄 것으로 추정되는 기간에 체계적으로 상각해야 하며 그 기간은 20년을 넘길 수 없습니다.","지식재산을 도면화·자료화·매뉴얼화해 유형화하고 테크노마트·전시회 같은 오프라인과 온라인 마케팅을 활용한다.":"기술을 도면·자료·매뉴얼의 형태로 정리해 두고 전시회나 온라인으로 알립니다.","지식재산을 매개로 금융서비스를 제공한다.":"창의기업형은 지식재산을 매개로 금융서비스를 제공하는 금융입니다.","지식재산의 상각은 비용으로 인정되어 당기순이익을 줄이고 납세금액을 줄어들게 만든다.":"상각은 비용으로 인정되어 당기순이익을 줄이고 납세액도 줄입니다.","지식재산의 이전·거래 활성화의 전제조건인 정확하고 신뢰도 있는 가치평가가 정착되지 못했다.":"거래를 살리는 전제인 정확하고 믿을 만한 가치평가가 아직 자리 잡지 못했습니다.","지식재산의 창출·사업화·활용 과정에서 지식재산을 기반으로 투자, 융자, 보증 등의 자금을 공급하는 금융 활동이다.":"IP금융은 지식재산을 믿고 돈을 대는 금융으로 투자, 융자, 보증이 모두 들어갑니다.","지식재산이 제품으로 판매되기 전에 제품과 사업지원 인프라 개발을 위한 상당한 선행투자가 필요하다.":"제품이 팔리기 전에는 제품과 사업 지원 인프라를 개발하는 큰 선행투자가 먼저 들어갑니다.","지식재산 자체를 수익창출 수단으로 한다.":"창의자본형은 지식재산 자체를 수익 수단으로 삼는 금융입니다.","지역, 기간, 제품·서비스 영역 등을 제한해 허여하는 경우가 있어 분쟁 소지를 막으려면 영역을 잘 설정해야 한다.":"지역·기간·제품 영역을 제한해 허여하는 일이 있어 분쟁을 막으려면 영역을 잘 설정해야 합니다.","질권의 설정등록 시 유질계약을 등록원인으로 등록하고 채무기업의 처분승낙서를 첨부":"질권 설정등록 때는 유질계약이 등록의 원인이 되고, 채무기업이 처분을 승낙한 서면이 첨부됩니다.","짧은 기간의 라이선스는 초기 선급금이 많고 경상 로열티는 상대적으로 적거나 아예 초기에 일시금으로 지급하는 방식이다.":"단기 라이선스는 초기 선급금이 많고 경상 로열티가 적거나 처음에 일시금으로 주는 방식입니다.","참여 기업 간의 상이한 목표와 지배력 수준 차이로 관리에 어려움이 있을 수 있다.":"참여 기업의 목표와 지배력이 달라 관리가 어려울 수 있습니다.","참여 기업의 보완적인 기술과 자원으로 리스크가 감소한다.":"참여 기업이 서로 부족한 기술과 자원을 채워 주므로 리스크가 줄어듭니다.","창업계획 단계: 사업 타당성 검토와 사전계획 수립으로 시행착오를 줄이고 사업계획서를 작성":"계획 단계에서는 사업 타당성을 미리 따져 시행착오를 줄이고 사업계획서를 만듭니다.","창업구상 단계: 구체적인 아이템을 정하기 전에 창업자의 역량을 점검하고 시장·기술 조사로 가장 적합한 아이템을 구상":"구상 단계에서는 창업자 역량을 점검하고 시장·기술 조사를 거쳐 가장 알맞은 아이템을 고릅니다.","창업구상 단계에는 사업 아이템 탐색 뒤에 선행기술 조사, 법적 문제점 검토, 지식재산 출원을 하는 지식재산 조사 분석이 포함된다.":"구상 단계에서는 아이템 탐색 뒤에 선행기술 조사, 법적 문제 검토, 지식재산 출원이 이어지는 조사 분석을 합니다.","채무불이행 시 담보IP 처분에 높은 전문성이 필요하다.":"돈을 못 갚으면 담보 IP를 팔아야 하는데 이 일에는 높은 전문성이 필요합니다.","채무불이행 이후 사후 평가로 지원 여부를 정하는 한계가 있었다.":"부도 뒤에야 평가해 지원 여부를 정하는 점이 한계였습니다.","채산성이 없거나 성장률이 낮을 것으로 예상되는 지식재산을 매각하고 주력업종에 집중하려는 동기이다.":"수익성 확보 동기는 채산성 없는 지식재산을 팔고 주력 업종에 집중하려는 것입니다.","채택 가능성이 높은 조건을 설정해 가장 효율적이고 효과적인 사용(highest and best use) 원칙을 적용해야 한다.":"평가 조건은 현실적으로 채택될 만한 것으로 정하고 최고 최선의 사용(highest and best use) 원칙을 따릅니다.","초과이익 배분방식, 순이익 배분방식, 결정수익 환원방식이 주로 사용된다.":"IP 몫을 가르는 방식으로 초과이익, 순이익, 결정수익 환원 세 가지가 주로 쓰입니다.","초기 창업자에게 사무 공간, 멘토링, 자금 지원, 네트워킹 기회 등을 제공해 창업을 돕는다.":"창업보육센터(인큐베이터)는 초기 창업자에게 사무 공간, 멘토링, 자금, 네트워킹을 제공합니다.","최근 AI를 활용해 금액이 아닌 등급으로 가치를 평가하는 시스템도 등장했다.":"최근에는 AI로 금액이 아닌 등급으로 가치를 평가하는 시스템도 나왔습니다.","최소한의 기술을 개시받은 뒤 일정한 검토기간이 지나 계약체결 여부를 결정하도록 하는 계약이다.":"Option Agreement는 최소한의 기술만 공개받고 검토기간 뒤에 계약 체결 여부를 정하는 계약입니다.","최초 인식 후 무형자산의 장부금액을 원가에서 상각누계액과 손상차손누계액을 차감한 금액으로 한다.":"원가모형은 최초 인식 뒤 원가에서 상각누계액과 손상차손누계액을 뺀 금액을 장부금액으로 합니다.","취득원가는 취득일 공정가치로 하며, 피취득자가 사업결합 전에 인식했는지와 관계없이 영업권과 분리해 별도 자산으로 인식한다.":"사업결합에서는 취득일 공정가치로 하고 피취득자의 이전 인식 여부와 관계없이 영업권과 떼어 별도 자산으로 인식합니다.","측정이 비교적 용이하다는 장점이 있다.":"비용접근법은 측정이 쉬운 것이 장점입니다.","친인척·지인·금융기관 차입처럼 주주나 출자자 투자 이외에 타인으로부터 조달하는 자금으로 상환 의무가 있다.":"타인자본은 친인척·지인·금융기관 차입처럼 투자금 밖에서 조달하는 자금이고 갚아야 합니다.","타인의 권리에 대해 라이선스를 도입하는 것":"라이선싱 인은 남의 권리에 대한 라이선스를 들여오는 쪽입니다.","특약사항으로 처분승낙서 내용과 공동담보 목록을 포함":"특약사항에는 처분승낙서 내용과 공동담보 목록을 넣습니다.","특정 라이선시에게만 사용 권한을 주고 다른 누구에게도 같은 권한을 주지 않는다.":"독점 라이선스에서는 한 라이선시만 권한을 받고 다른 누구도 같은 권한을 받지 못합니다.","특정 시장 공략을 위해 상대 기업의 전문화된 기술을 활용하는 것":"수평적 제휴는 특정 시장을 노리고 상대 기업의 전문 기술을 쓰는 형태입니다.","특허권의 전용실시권은 등록이 효력 발생요건이다.":"특허의 전용실시권은 등록해야 효력이 생깁니다.","특허권이나 상표처럼 성격상 독특한 지식재산은 활성시장이 존재할 수 없어 재평가모형 적용이 어렵다.":"특허권이나 상표는 성격이 독특해 활성시장이 있을 수 없으므로 재평가모형을 적용하기 어렵습니다.","특허의 실시권 허여 계약이다.":"Patent License Agreement는 특허의 실시권을 주는 계약입니다.","특허청은 모태펀드 특허계정에 550억 원을 출자하면서 특허기술 사업화 등 정책적 투자대상에 투자하는 IP투자펀드를 조성했다.":"특허청이 모태펀드 특허계정에 550억 원을 넣어 특허기술 사업화 등에 투자하는 IP투자펀드를 만든 해입니다.","판매가 없어도 최저 금액을 낸다.":"최저 기술료는 팔리지 않아도 최저 금액을 냅니다.","평가 IP로 인해 발생하는 사업제품에 관련된 복수의 기술구성요소 중 평가 IP가 보호하는 비중을 뜻한다.":"이용률은 사업제품의 여러 기술 구성요소 가운데 평가 IP가 보호하는 비중입니다.","평가 결과는 관점과 평가요인에 따라 달라질 수 있어 평가의 목적과 용도를 명시해야 하며, 이는 평가보고서의 분석내용과 평가금액이 유효하게 적용되는 범위를 결정한다.":"결과가 관점과 요인에 따라 달라지므로 목적과 용도를 밝혀 보고서의 분석과 금액이 유효한 범위를 정합니다.","평가대상과 동일·유사한 지식재산이 활성 시장에서 거래된 가격에 근거해 상대적 가치를 산정하는 방법이다.":"시장접근법은 비슷한 지식재산이 활성 시장에서 거래된 가격으로 상대 가치를 구합니다.","평가대상과 유사한 자산의 거래정보가 많을 때 최적의 방법이며 라이선스 조건이나 로열티 결정에 자주 이용된다.":"비슷한 거래정보가 많을 때 최적이며 라이선스 조건이나 로열티를 정할 때 자주 이용됩니다.","평가대상의 경제적 수명기간에 사업화로 발생할 경제적 이익을 추정해 할인율로 현재가치로 환산하는 방법이다.":"소득접근법은 경제적 수명 동안 사업화로 생길 이익을 추정해 할인율로 현재가치로 바꿉니다.","평가대상이 권리 자체이므로 IP에 중대한 권리 하자가 있으면 가치산정이 무의미할 수 있어, 권리성 분석의 역할이 기술가치평가보다 훨씬 중요하다.":"권리에 큰 하자가 있으면 가치 산정 자체가 헛수고가 될 수 있어, 권리성 분석이 기술가치평가보다 훨씬 비중이 큽니다.","평가자는 원칙적으로 실태조사로 대상 IP기술을 확인하되 객관적이고 신뢰할 자료가 충분하면 실태조사를 생략할 수 있다.":"원칙은 현장 조사로 대상 IP기술을 확인하는 것이지만 믿을 자료가 충분하면 조사를 생략합니다.","피취득자가 진행 중인 연구·개발 프로젝트는 자산의 정의를 충족하고 분리 가능하거나 계약상·법적 권리에서 발생하면 무형자산의 정의를 충족한다.":"진행 중인 연구·개발도 자산의 정의를 충족하고 분리 가능하거나 계약상·법적 권리에서 나오면 무형자산에 해당합니다.","필요한 기술의 권리를 받아 제품 가치를 높이고, 해당 권리로 인한 분쟁 위험도 제거해 안정적으로 사업을 할 수 있다.":"필요한 권리를 받아 제품 가치를 높이고 권리 분쟁 위험도 없애 안정적으로 사업합니다.","한 기업이 다른 기업이 개발한 제품을 시장에 판매하여 수익 일부를 얻는 것":"수직적 제휴는 한 기업이 남이 개발한 제품을 시장에 팔고 수익 일부를 얻는 형태입니다.","할인현금흐름으로 사업가치를 산정":"IP요소법의 평가 순서는 먼저 할인현금흐름으로 사업가치를 산정하는 것입니다.","할인현금흐름으로 얻은 사업가치는 사업가·투자자·채권자와 IP 제공자가 나누어야 할 총액이므로 평가액이 바로 나오지 않고 IP 기여분의 배분 문제가 남는다.":"사업가치는 사업가·투자자·채권자와 IP 제공자가 나눌 총액이라 평가액이 바로 나오지 않고 IP 기여분 배분이 남습니다.","해당 기술로 제품을 개발할 수 있어 중소기업과 스타트업에 중요한 전략 수단이 된다.":"라이선시는 그 기술로 제품을 만들 수 있어 중소기업과 스타트업에게 중요한 전략 수단입니다.","핵심 라이선스 기술이 표준일 때는 개량기술이 표준에 통합되지 못하면 쓸모가 거의 없어, 라이선서가 라이선시의 개량기술에 대한 권리를 보유하는 것이 특히 중요하다.":"표준 기술이 핵심이면 개량기술이 표준에 편입되지 않는 한 쓸모가 거의 없어 라이선서가 개량기술 권리를 갖는 쪽이 낫습니다.","혁신적인 기술이나 아이디어로 새 시장을 만들어 제품·서비스를 생산·판매하는 창업 형태로, 지식재산의 보호와 활용이 중요하다.":"새로운 기술로 시장을 만들고 제품을 파는 창업이라, 지식재산을 어떻게 지키고 쓰느냐가 성패를 가릅니다.","현금흐름 추정기간, 연도별 잉여현금흐름, 할인율, IP기여도, 이용률 다섯 가지 변수를 추정해야 한다.":"IP요소법에서는 추정기간, 잉여현금흐름, 할인율, IP기여도, 이용률 다섯 값을 정해야 합니다.","현물출자 금액 산정, 직무발명 보상금액 결정":"가치평가는 현물출자 금액을 정하거나 직무발명 보상금을 정할 때도 쓰입니다.","후발주자의 시장 진입을 차단하는 무기가 된다.":"지식재산권이 있으면 늦게 뛰어드는 경쟁자를 막는 무기가 됩니다.","후속 연구개발 같은 연속적 투자와 단계별 수익을 평가에 포함하지 못하고, 연관 프로젝트의 보완성이나 경영의 유연성·전략적 옵션을 반영하기 어렵다.":"후속 연구 같은 단계별 투자와 수익, 경영의 유연성과 전략적 옵션은 소득접근법이 담아내기 어렵습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
